CREATE FUNCTION verundentsorgung.admin_add_objektklassen(vschemaname text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
vZ            integer default 0;
vSQL          text default 'Fehler!';
vscript       text default 'Fehler!';
vdummy        text default 'Fehler!';
rc            RECORD;
begin
	--Aufruf select verundentsorgung.admin_add_objektklassen('verundentsorgung');
for rc in select substring(langtext,1,2) fachschale
     , case substring(langtext,4,3) when 'pkt' then 'point' when 'lin' then 'linestring' when 'fla' then 'polygon' end geometrietyp
     , trim(langtext) langtext from verundentsorgung.st_vw_objektbezeichnung 
        where langtext not in ('unbekannt') loop	
select count(*) into vZ from pg_tables t where t.schemaname = vschemaname and t.tablename = rc.langtext;
if vZ = 0 then 
vSQL    := 'CREATE TABLE '||vschemaname||'.'||rc.langtext||' (
	id                      text NOT NULL DEFAULT uuid_generate_v4(),
	fid_hist 	            text NOT NULL DEFAULT ''unbekannt''::text,
	name_number             text NOT NULL DEFAULT ''unbekannt''::text,
	gueltig_von             timestamp NOT NULL DEFAULT now(),
	gueltig_bis             timestamp NOT NULL DEFAULT ''2100-01-01 00:00:00''::timestamptz,
	angelegt_am             timestamp NOT NULL DEFAULT now(),
	angelegt_von            text NOT NULL DEFAULT ''unbekannt''::text,
	geaendert_am            timestamp NOT NULL DEFAULT now(),
	geaendert_von           text NOT NULL DEFAULT ''unbekannt''::text,
	leistungsobjekt         text NOT NULL DEFAULT ''unbekannt''::text,
	bemerkung               text NOT NULL DEFAULT ''noch keine Bemerkung''::text,
	id_st_strasse           text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	hausnummer              text NOT NULL DEFAULT ''unbekannt''::text,
	hausnummerzusatz        text NOT NULL DEFAULT ''unbekannt''::text,
	lagezusatz              text NOT NULL DEFAULT ''unbekannt''::text,
	herkunftsplan           text NOT NULL DEFAULT ''unbekannt''::text,
	id_st_vw_projekt        text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_betriebsstatus text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_eigentuemer    text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_betreiber      text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_material       text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_medium         text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
	id_st_vw_lagestatus     text NOT NULL DEFAULT ''00000000-0000-0000-0000-000000000000''::text,
    geometry                public.geometry('||rc.geometrietyp||', 25833) not null,
	CONSTRAINT              pk_'||rc.langtext||' PRIMARY KEY (id),
	CONSTRAINT              uk1_'||rc.langtext||' UNIQUE (id_st_vw_projekt, name_number),
	CONSTRAINT              fk_'||rc.langtext||'_st_strasse           FOREIGN KEY (id_st_strasse)           REFERENCES '||vschemaname||'.st_strasse(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_projekt        FOREIGN KEY (id_st_vw_projekt)        REFERENCES '||vschemaname||'.st_vw_projekt(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_betriebsstatus FOREIGN KEY (id_st_vw_betriebsstatus) REFERENCES '||vschemaname||'.st_vw_betriebsstatus(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_eigentuemer    FOREIGN KEY (id_st_vw_eigentuemer)    REFERENCES '||vschemaname||'.st_vw_eigentuemer(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_betreiber      FOREIGN KEY (id_st_vw_betreiber)      REFERENCES '||vschemaname||'.st_vw_betreiber(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_material       FOREIGN KEY (id_st_vw_material)       REFERENCES '||vschemaname||'.st_vw_material(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_medium         FOREIGN KEY (id_st_vw_medium)         REFERENCES '||vschemaname||'.st_vw_medium(id),
	CONSTRAINT              fk_'||rc.langtext||'_st_vw_lagestatus     FOREIGN KEY (id_st_vw_lagestatus)     REFERENCES '||vschemaname||'.st_vw_lagestatus(id)
)'; raise info '%', vSQL; execute vSQL;
end if;
end loop;
return vZ::text;
end; $$;


