vSQL := '
WITH line_data AS (
  SELECT ( $1 ) AS geom
),
vertices AS (
  SELECT (ST_DumpPoints(geom)).geom AS pt FROM line_data
)
SELECT 
  (ST_Dump(
    ST_Split(
      (SELECT geom FROM line_data), 
      ST_Union(pt)
    )
  )).geom AS split_segment
FROM vertices';
for vRC in execute vSQL using vgeometry loop --
vSPLIT_SEGMENT := vrc.split_segment;  if vNOTICE = 1 then raise notice '%', vSPLIT_SEGMENT::text; end if;
--
vZ := vZ+1;                           if vNOTICE = 1 then raise notice '%', concat('vZ: ', vZ::text); end if;
vlaenge = st_length(vSPLIT_SEGMENT);  if vNOTICE = 1 then raise notice '%', concat('vlaenge: ', vlaenge::text); end if;
--laufendenummer_in_geometrie

vrichtungswinkel := degrees(st_azimuth(st_startpoint(vSPLIT_SEGMENT), st_endpoint(vSPLIT_SEGMENT)))::numeric ;                               if vNOTICE = 1 then raise notice '%', concat('vrichtungswinkel: ', vrichtungswinkel::text); end if;
vpkt_vektormitte := st_lineinterpolatepoint(st_makeline(st_startpoint(vSPLIT_SEGMENT), st_endpoint(vSPLIT_SEGMENT)), 0.5::double precision); if vNOTICE = 1 then raise notice '%', concat('vpkt_vektormitte: ', vpkt_vektormitte::text); end if;
