    , ( select id from verundentsorgung.admin_benutzergruppe where benutzergruppe = 'verundentsorgung_erfasser_ka_zvg_gruppe' ) id_admin_benutzergruppe
    , '00000000-0000-0000-0000-000000000001'::uuid id_st_vw_projekt
  from verundentsorgung.admin_benutzer b 
    where (vorname, nachname) in (
select 'Tom', 'Liebing' )
) A where ( a.id_admin_benutzer, a.id_admin_benutzergruppe, a.id_st_vw_projekt ) not in ( select id_admin_benutzer, id_admin_benutzergruppe, id_st_vw_projekt from verundentsorgung.admin_benutzer2admin_benutzergruppe )
;
