select b.id id_admin_benutzer
    , ( select id from verundentsorgung.admin_benutzergruppe where benutzergruppe = 'verundentsorgung_viewer_zvg_gruppe' ) id_admin_benutzergruppe
    , '00000000-0000-0000-0000-000000000001'::uuid id_st_vw_projekt
  from verundentsorgung.admin_benutzer b 
    where (vorname, nachname) in (
select 'Tom', 'Liebing'   union
select 'Heiner', 'Rieger' union
select 'Mathias', 'Arndt' )
) A where ( a.id_admin_benutzer, a.id_admin_benutzergruppe, a.id_st_vw_projekt ) not in ( select id_admin_benutzer, id_admin_benutzergruppe, id_st_vw_projekt from verundentsorgung.admin_benutzer2admin_benutzergruppe )
;
--
--
--
create or replace view verundentsorgung.admin_benutzer2admin_benutzergruppe_v as
select 
  b.anmeldename, bg.benutzergruppe 
  , case when bg.benutzergruppe = 'verundentsorgung_viewer_zvg_gruppe' then '%'
         when bg.benutzergruppe = 'verundentsorgung_erfasser_zvg_gruppe' then '%'
         when bg.benutzergruppe = 'verundentsorgung_erfasser_wa_zvg_gruppe' then 'wa'
         when bg.benutzergruppe = 'verundentsorgung_erfasser_aw_zvg_gruppe' then 'aw'
         when bg.benutzergruppe = 'verundentsorgung_erfasser_ka_zvg_gruppe' then 'ka'
         else null end tabellenpraefix 
  , case when position('viewer' in bg.benutzergruppe)   > 0 then 'select' 
         when position('erfasser' in bg.benutzergruppe) > 0 then 'select, insert, update, delete' end datenbankrecht
  , b.vorname, b.nachname, b.email, b.titel, b.id_st_vw_projekt, p.kurztext projektname, b.id id_admin_benutzer, bg.id id_admin_benutzergruppe, b2bg.id id_admin_benutzer2admin_benutzergruppe
  , p.gueltig_bis gueltig_bis_st_vw_projekt , b.gueltig_bis gueltig_bis_admin_benutzer, bg.gueltig_bis gueltig_bis_admin_benutzergruppe, b2bg.gueltig_bis gueltig_bis_admin_benutzer2admin_benutzergruppe     
from  verundentsorgung.admin_benutzer b
    , verundentsorgung.admin_benutzer2admin_benutzergruppe b2bg
    , verundentsorgung.admin_benutzergruppe bg
    , verundentsorgung.st_vw_projekt p
where b.id_st_vw_projekt = p.id
  and b.id  = b2bg.id_admin_benutzer and b.id_st_vw_projekt = b2bg.id_st_vw_projekt
  and bg.id = b2bg.id_admin_benutzergruppe and bg.id_st_vw_projekt = b2bg.id_st_vw_projekt
  order by anmeldename, benutzergruppe;
