    vSQL := 'ALTER ROLE '||vRCFS.anmeldename||' inherit';              raise notice '%', vSQL||';'; execute vSQL; --implizite Vererbung
  execute vSQL;
end loop;
-------------------------------------------------------------------------------------------------------
-----------------------------------Ende Rollen an Benutzern verteilen----------------------------------
-------------------------------------------------------------------------------------------------------
--
-------------------------------------------------------------------------------------------------------
-----------------------------------Anfang Rechte an Rollen verteilen-----------------------------------
-------------------------------------------------------------------------------------------------------
for vRCFS in ( 
----------------------
select t.*, bg.benutzergruppe, bg.tabellenpraefix,
    coalesce ( 
   (case when t.quelle = 'view' then 'select' else
   (case when t.quelle = 'function' then 'execute' else
   (case when bg.benutzergruppe = 'verundentsorgung_viewer_zvg_gruppe'   then 'select' else
   (case when bg.benutzergruppe = 'verundentsorgung_erfasser_zvg_gruppe' then 'select, insert, update, delete' else
   (case when bg.tabellenpraefix = substring(t.objektname,1,2) then bg.datenbankrecht end
    )  end ) end ) end ) end ), 'select' ) 
    --, 'select, insert update, delete', 'select') end 
    datenbankrecht 
    from  
  (
    --Views
    select 'view'::text     quelle, table_schema::text schema_name, table_name::text objektname from information_schema.views where table_schema = 'verundentsorgung'
      --and ( table_schema::text, table_name::text) in ( select table_schema::text, table_name::text from information_schema.views ) 
      and ( substring( table_name, 1, 3 ) in ('al_', 'aw_', 'ka_', 'so_', 'st_', 'ta_', 'wa_') or table_name in ('strassenschluessel_v') ) union  
    --Tabellen
    select 'table'::text    quelle, table_schema::text schema_name, table_name::text objektname from information_schema.tables where table_schema = 'verundentsorgung' 
      and ( table_schema::text, table_name::text) not in ( select table_schema::text, table_name::text from information_schema.views ) 
      and ( substring( table_name, 1, 3 ) in ('al_', 'aw_', 'ka_', 'so_', 'st_', 'ta_', 'wa_') or table_name in ('dokument', 'dokument_objekt', 'admin_projekt_parameter') ) union 
    --Funktionen
    select 'function'::text quelle, nspname::text      schema_name, proname::text    objektname FROM pg_catalog.pg_namespace JOIN pg_catalog.pg_proc ON pronamespace = pg_namespace.oid where nspname = 'verundentsorgung'
      and proname not like 'migration%' and proname not like 'admin%'
  ) t, 
  ( select distinct benutzergruppe, tabellenpraefix , datenbankrecht from verundentsorgung.admin_benutzer2admin_benutzergruppe_v ) bg
  --on ( case when bg.tabellenpraefix = '%' then 'XXX' else bg.tabellenpraefix end = case when substring(t.objektname,1,2) in ('aw', 'wa', 'ka') then substring(t.objektname,1,2) else 'XXX' end )
  --and bg.tabellenpraefix in ('aw', 'wa', 'ka') and substring(t.objektname,1,2) in ('aw', 'wa', 'ka') 
order by 2,3,1
----------------------
             ) loop
--vSQL := 'ALTER '||vRCFS.quelle||' "'||vRCFS.schema_name||'"."'||vRCFS.objektname||'" OWNER TO gis'; raise notice '%', vSQL||';'; 
  --execute vSQL;
if vRCFS.quelle in ('table', 'function') then
    vSQL := 'GRANT '||vRCFS.datenbankrecht||' on '||vRCFS.quelle||' "'||vRCFS.schema_name||'"."'||vRCFS.objektname||'" TO '||vRCFS.benutzergruppe; 
  elseif vRCFS.quelle in ('view') then
    vSQL := 'GRANT '||vRCFS.datenbankrecht||' on "'||vRCFS.schema_name||'"."'||vRCFS.objektname||'" TO '||vRCFS.benutzergruppe;
