         when bg.benutzergruppe = ''verundentsorgung_erfasser_aw_zvg_gruppe'' then ''aw''
         when bg.benutzergruppe = ''verundentsorgung_erfasser_ka_zvg_gruppe'' then ''ka''
         else null end tabellenpraefix 
  , case when position(''viewer'' in bg.benutzergruppe)   > 0 then ''select'' 
         when position(''erfasser'' in bg.benutzergruppe) > 0 then ''select, insert, update, delete'' end datenbankrecht
  , b.vorname, b.nachname, b.email, b.titel, b.id_st_vw_projekt, p.kurztext projektname, b.id id_admin_benutzer, bg.id id_admin_benutzergruppe, b2bg.id id_admin_benutzer2admin_benutzergruppe
  , p.gueltig_bis gueltig_bis_st_vw_projekt , b.gueltig_bis gueltig_bis_admin_benutzer, bg.gueltig_bis gueltig_bis_admin_benutzergruppe, b2bg.gueltig_bis gueltig_bis_admin_benutzer2admin_benutzergruppe     
from  verundentsorgung.admin_benutzer b
    , verundentsorgung.admin_benutzer2admin_benutzergruppe b2bg
    , verundentsorgung.admin_benutzergruppe bg
