CREATE FUNCTION verundentsorgung.admin_error_log(verror_state text, verror_text text, verror_detail text, verror_hint text, verror_context text, verror_bemerkung text, vid_st_vw_projekt text, verror_table_schema text, verror_table_name text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    vSQL              VARCHAR;
    vSCHEMA_NAME      text default 'verundentsorgung';
    vwert_aktivstatus integer;
    vNOTICE           text default '1';
--
    vpid              VARCHAR;
    vdatname          VARCHAR;
    vapplication_name VARCHAR;
    vclient_addr      VARCHAR;
    vclient_hostname  VARCHAR;
    vclient_port      VARCHAR;
    vbackend_type     VARCHAR;
--
BEGIN
/*vSQL := 'select wert_aktivstatus --, wert_numerisch, wert_text, wert_timestamp, id_st_vw_projekt, notiz, fehlermeldung 
           from '||vSCHEMA_NAME||'.admin_projekt_parameter 
             where kurztext = $1 and id_st_vw_projekt = $2'; 
execute vSQL into vwert_aktivstatus using 'write_errorlog',  vid_st_vw_projekt; --, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_VARCHAR, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung using vPROJEKTPARAMETER_WERT_KURZTEXT, new.id_st_vw_projekt;
*/
select (verundentsorgung.admin_select_admin_projekt_parameter('write_errorlog', vid_st_vw_projekt )).vwert_aktivstatus into vwert_aktivstatus;
if vwert_aktivstatus = 1 then
  --if vNOTICE = '1' then raise notice '%','Trace01'; end if;
--
vSQL := 'select pid::text pid, datname, application_name, client_addr, client_hostname, client_port, backend_type 
             from pg_stat_activity where pid = pg_backend_pid()'; 
  execute vSQL into vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type;
--
vSQL := '
  INSERT INTO '||vSCHEMA_NAME||'.admin_error_log (
    error_pid               ,
    error_datname           ,
    error_application_name  ,
    error_client_addr       ,
    error_client_hostname   ,
    error_client_port       ,
    error_backend_type      ,
    --
    error_state             ,
    error_message           , 
    error_detail            , 
    error_hint              ,
    error_context           ,
    --
    error_bemerkung         ,
    error_id_st_vw_projekt  ,
    error_table_schema      ,
    error_table_name
)
   select p.vpid, p.vdatname, p.vapplication_name, p.vclient_addr, p.vclient_hostname, p.vclient_port, p.vbackend_type
        , e.verror_state, e.verror_text, e.verror_detail, e.verror_hint, e.verror_context, e.verror_bemerkung, e.vid_st_vw_projekt, e.verror_table_schema, e.verror_table_name
 --    from (select pid::text pid, datname, application_name, client_addr, client_hostname, client_port, backend_type from pg_stat_activity where pid = $1 ) p,
       from (select $1 vpid, $2 vdatname, $3 vapplication_name, $4 vclient_addr, $5 vclient_hostname, $6 vclient_port, $7 vbackend_type ) p,
 --         (select $2 error_state, $3 error_text,  $4 error_detail,  $5 error_hint,  $6 error_context,  $7 error_bemerkung,  $8 id_st_vw_projekt ) e 
            (select $8 verror_state, $9 verror_text, $10 verror_detail, $11 verror_hint, $12 verror_context, $13 verror_bemerkung, $14 vid_st_vw_projekt, $15 verror_table_schema text, $16 verror_table_name ) e 
';
-- nicht mehr aktuell execute vSQL using pg_backend_pid(), verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt; 
--execute vSQL using vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type, verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt; 
vSQL := '
  INSERT INTO '||vSCHEMA_NAME||'.admin_error_log (
    error_pid               ,
    error_datname           ,
    error_application_name  ,
    error_client_addr       ,
    error_client_hostname   ,
    error_client_port       ,
    error_backend_type      ,
    error_state             ,
    error_message           , 
    error_detail            , 
    error_hint              ,
    error_context           ,
    error_bemerkung         ,
    error_id_st_vw_projekt  ,
    error_table_schema      ,
    error_table_name
)
   select p.vpid, p.vdatname, p.vapplication_name, p.vclient_addr, p.vclient_hostname, p.vclient_port, p.vbackend_type
        , e.verror_state, e.verror_text, e.verror_detail, e.verror_hint, e.verror_context, e.verror_bemerkung, e.vid_st_vw_projekt, e.verror_table_schema, e.verror_table_name
       from (select '''||vpid||''' vpid, '''||vdatname||''' vdatname, '''||vapplication_name||''' vapplication_name, '''||vclient_addr||''' vclient_addr, '''||vclient_hostname||''' vclient_hostname, '''||vclient_port||''' vclient_port, '''||vbackend_type||''' vbackend_type ) p,
            (select '''||verror_state||''' verror_state, '''||verror_text||''' verror_text, '''||verror_detail||''' verror_detail, '''||verror_hint||''' verror_hint, '''||verror_context||''' verror_context, '''||verror_bemerkung||''' verror_bemerkung, '''||vid_st_vw_projekt||''' vid_st_vw_projekt, '''||verror_table_schema||''' verror_table_schema, '''||verror_table_name||''' verror_table_name ) e 
'; --, vpid::text, vdatname::text, vapplication_name::text, vclient_addr::text, vclient_hostname::text, vclient_port::text, vbackend_type::text, verror_state::text, verror_text::text, verror_detail::text, verror_hint::text, verror_context::text, verror_bemerkung::text, vid_st_vw_projekt::text, verror_table_schema::text, verror_table_name::text ) ;
PERFORM dblink_exec('dblink_fdw_localhost_gis_verundentsorgung', vSQL);
--
if vNOTICE = '1' then raise notice '%','Trace02'; end if;
end if; --if vwert_aktivstatus = 1 then
if vNOTICE = '1' then raise notice ' % % % % % % % % % % ', verror_state::text, verror_text::text, verror_detail::text, verror_hint::text, verror_context::text, verror_bemerkung::text, vid_st_vw_projekt::text, pg_backend_pid()::text, verror_table_schema::text, verror_table_name::text ; end if;
END;
$_$;


