--select verundentsorgung.admin_layerstruktur2admin_symbole_mv_refresh ('verundentsorgung', '00000000-0000-0000-0000-000000000001'::uuid, '1', '1');
--
--
begin
vSQL := 'select kurztext from "'||vtable_schema||'".st_vw_projekt where id = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL into vst_vw_projekt_kurztext using vid_st_vw_projekt; end if;
vSQL := 'create table if not exists "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" as select * from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole" where 1 = 2'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if;
vSQL := 'delete from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" where projekt = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vst_vw_projekt_kurztext; end if;
vSQL := 'insert into "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" select * from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole" where projekt = $1 order by case when symbol_objektklasse like ''%lin%'' then line_style else pkt_symbol_size end '; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vst_vw_projekt_kurztext; end if;
--vacuum full verundentsorgung.admin_layerstruktur2admin_symbole_mv;
vSQL := 'analyze "'||vtable_schema||'".admin_layerstruktur2admin_symbole_mv'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if;
return vRETURN;
--RAISE EXCEPTION 'Ein Fehler ist aufgetreten';
/*
EXCEPTION
  WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS 
    verror_state  = RETURNED_SQLSTATE,
    verror_text   = MESSAGE_TEXT,
    verror_detail = PG_EXCEPTION_DETAIL,
    verror_hint   = PG_EXCEPTION_HINT,
    verror_context= PG_EXCEPTION_CONTEXT;
    PERFORM verundentsorgung.f_admin_error_log( verror_state, verror_text, verror_detail, verror_hint, verror_context, 'admin_layerstruktur2admin_symbole_mv', vid_st_vw_projekt );
RAISE;
*/
end; $_$;


--
-- TOC entry 24673 (class 1255 OID 44934778)
-- Name: admin_layerstruktur2st_vw_kartenlayout(text, uuid, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.admin_layerstruktur2st_vw_kartenlayout(vtable_schema text, vid_st_vw_projekt uuid, vnotice text, vexecute text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vZ       integer default 0;
vSQL     text;
vRETURN  text default '1';
vst_vw_projekt_kurztext text;
--
  verror_state      text;
  verror_text       text;
  verror_detail     text;
  verror_hint       text;
  verror_context    text;
--
--select verundentsorgung.admin_layerstruktur2st_vw_kartenlayout ('verundentsorgung', '00000000-0000-0000-0000-000000000001'::uuid, '1', '1');
--
begin
vSQL := 'select kurztext from "'||vtable_schema||'".st_vw_projekt where id = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL into vst_vw_projekt_kurztext using vid_st_vw_projekt; end if;
--vSQL := 'create table if not exists "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" as select * from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole" where 1 = 2'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if;
vSQL := 'delete from "'||vtable_schema||'"."st_vw_kartenlayout" where id_st_vw_projekt = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vid_st_vw_projekt; end if;
vSQL := 'insert into "'||vtable_schema||'"."st_vw_kartenlayout" (
  id_st_vw_projekt
, anzahl
, projekt
, medium
, objekttyp
, objektklasse
, symbol
, medium_filter
, betriebsstatus_filter
, lagestatus_filter
, eigentuemer_filter
, betreiber_filter
, darstellung
, rgb_farbe
, strichstaerke_mm
, line_style
, line_color
, line_alpha
, line_width
, line_width_unit
, pkt_symbolname
, pkt_symbolnamelang
, pkt_stroke_color
, pkt_fill_color
, pkt_stroke_with
, pkt_symbol_size
, pkt_symbol_angle
, medium_gruppe
, symbolname
, symbolname_langtext
, symbol_objektklasse
, symbol_objekttyp
, zeile
)
--
SELECT 
    $1 id_st_vw_projekt,
    a.anzahl,
    a.projekt,
    a.medium,
    a.objekttyp,
    a.objektklasse,
    a.symbol,
    --a.medium_filter_alt,
    a.medium_filter,
    a.betriebsstatus_filter,
    a.lagestatus_filter,
    a.eigentuemer_filter,
    a.betreiber_filter,
    a.darstellung,
    a.rgb_farbe,
    a.strichstaerke_mm,
    a.line_style,
    a.line_color,
    a.line_alpha,
    a.line_width,
    a.line_width_unit,
    a.pkt_symbolname,
    a.pkt_symbolnamelang,
    a.pkt_stroke_color,
    a.pkt_fill_color,
    a.pkt_stroke_with,
    a.pkt_symbol_size,
    a.pkt_symbol_angle,
    a.medium_gruppe,
    a.symbolname,
    a.symbolname_langtext,
    a.symbol_objektklasse,
    a.symbol_objekttyp,
    --a.symbolname_alt,
    a.zeile
   FROM ( SELECT DISTINCT count(*) AS anzahl,
            l.projekt,
            l.medium,
            l.objekttyp,
            l.objektklasse,
            l.symbol,
            l.medium_filter_alt,
            l.medium_filter,
            l.betriebsstatus_filter,
            l.lagestatus_filter,
            l.eigentuemer_filter,
            l.betreiber_filter,
            l.darstellung,
            l.rgb_farbe,
            l.strichstaerke_mm,
            l.line_style,
            l.line_color,
            l.line_alpha,
            l.line_width,
            l.line_width_unit,
            l.pkt_symbolname,
            l.pkt_symbolnamelang,
            l.pkt_stroke_color,
            l.pkt_fill_color,
            l.pkt_stroke_with,
            l.pkt_symbol_size,
            l.pkt_symbol_angle,
            l.medium_gruppe,
            s.symbolname,
            s.symbolname_langtext,
            s.objektklasse AS symbol_objektklasse,
            s.objekttyp AS symbol_objekttyp,
            s.symbolname_alt,
            l.zeile
           FROM "'||vtable_schema||'".admin_layerstruktur l,
                "'||vtable_schema||'".admin_symbole s
          WHERE l.projekt::text = s.projekt::text AND ("position"(s.objektklasse::text, l.objektklasse::text) > 0 OR "position"(l.objektklasse::text, s.objektklasse::text) > 0)
