--
-- TOC entry 24715 (class 1255 OID 51483594)
-- Name: dgm_interpolation(double precision, double precision); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.dgm_interpolation(px double precision, py double precision) RETURNS double precision
    LANGUAGE plpgsql STRICT
    AS $$
DECLARE
    z1 float8; --Z Koordinate
    z2 float8;
    z3 float8;
    z4 float8;
    a1 float8; --Abstand
    a2 float8;
    a3 float8;
    a4 float8;
    vRC record;
    vSQL text;
    vZ integer default 0;
--zum Interpolieren
    w_a1 float8;
    w_b1 float8;
    w_c1 float8;
    w_d1 float8;
    sum_weights float8;
    z float8; --Rückgabewert
BEGIN
    vSQL := 'select a.*, x-'||px||' xdiff, y-'||py||' ydiff from (
               select id, x, y, z, st_distance( t.geometry, ST_GeomFromText(''POINT('||px||' '||py||')'', 25833) ) abstand 
                 from dgm_nwm_2012.dgm5_nwm_2012 t
                   where st_intersects(t.geometry, st_buffer( ST_GeomFromText(''POINT('||px||' '||py||')'', 25833), SQRT(50) ) )
                     and st_distance( t.geometry, ST_GeomFromText(''POINT('||px||' '||py||')'', 25833) ) <= SQRT(50) 
                                                                      ) a 
                where abs(x-'||px||') < 5 and abs(y-'||py||') < 5 limit 4';
for vRC in execute vSQL loop
vZ := vZ + 1;
  if       vZ = 1 then z1 := vRC.z; a1 := vRC.abstand; 
    elseif vZ = 2 then z2 := vRC.z; a2 := vRC.abstand; 
    elseif vZ = 3 then z3 := vRC.z; a3 := vRC.abstand; 
    elseif vZ = 4 then z4 := vRC.z; a4 := vRC.abstand; 
  end if;
end loop;
--
-- Jetzt habe ich die Abstände zu den Punkten, in dessen Quadrat ich mich befinde unbd dessen Höhen
-- Jetzt kann ich mit diesen Angaben interpolieren.
--select dgm_nwm_2012.interpolieren_auf_abstand(a1, z1, a2, z2, a3, z3, a4, z4) into z;
    -- Falls ein Abstand 0 ist: exakten Wert zurückgeben (Y1 liegt genau auf diesem Punkt!)
    IF a1 = 0 THEN RETURN z1; END IF;
    IF a2 = 0 THEN RETURN z2; END IF;
    IF a3 = 0 THEN RETURN z3; END IF;
    IF a4 = 0 THEN RETURN z4; END IF;
    -- IDW mit p=2
    w_a1 := 1/(a1*a1);
    w_b1 := 1/(a2*a2);
    w_c1 := 1/(a3*a3);
    w_d1 := 1/(a4*a4);
    sum_weights := w_a1 + w_b1 + w_c1 + w_d1;
    --
    z := (w_a1*z1 + w_b1*z2 + w_c1*z3 + w_d1*z4) / sum_weights;
    RETURN z;
END;
$$;


