       from (select $1 vpid, $2 vdatname, $3 vapplication_name, $4 vclient_addr, $5 vclient_hostname, $6 vclient_port, $7 vbackend_type ) p,
 --         (select $2 error_state, $3 error_text,  $4 error_detail,  $5 error_hint,  $6 error_context,  $7 error_bemerkung,  $8 id_st_vw_projekt ) e 
            (select $8 verror_state, $9 verror_text, $10 verror_detail, $11 verror_hint, $12 verror_context, $13 verror_bemerkung, $14 vid_st_vw_projekt ) e 
';
-- nicht mehr aktuellexecute vSQL using pg_backend_pid(), verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt; 
