            (select %L verror_state, %L verror_text, %L verror_detail, %L verror_hint, %L verror_context, %L verror_bemerkung, %L vid_st_vw_projekt ) e 
', vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type, verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt);
