				--if ( NEW.gueltig_bis < now()::timestamp ) THEN
				--		RAISE EXCEPTION 'Es wird versucht ein lebendes Objekt mit bereits vorhandenem Attribut ident_hist zu erzeugen.';
				--END IF;
  end if; --if vaktivstatus_ident_hist = 0 then
                RETURN NEW;
		END
$_$;


