--
-- TOC entry 24683 (class 1255 OID 46620769)
-- Name: label_def(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_def(vid text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    tmp text;
	vtotal_length numeric;
BEGIN
    -- Get vtotal_length from your custom function
select laenge into vtotal_length from  verundentsorgung.aw_lin_haltung where id = vid::uuid;  

SELECT
  COALESCE(
    CASE 
      WHEN F.kurztext IN ('ADL','ADL_GAL','VS_GAL','VS_TRL') THEN
        COALESCE(
          CASE WHEN F.kurztext IN ('ADL','ADL_GAL','RDL','RDL_GAL') THEN 'ADL ' ELSE 'Vakuum ' END, ''
        ) ||
        COALESCE(M.kurztext, '') ||
        COALESCE(
          CASE WHEN M.kurztext IN ('GG', 'GGG', 'AZ', 'ST') THEN
            CASE WHEN S.nennweite::numeric > 0 THEN ' DN ' || COALESCE(S.nennweite::text, '') ELSE '' END
          ELSE
            COALESCE(
              CASE WHEN S.AUSSENDURCHMESSER::numeric > 0 THEN ' d ' || COALESCE(S.AUSSENDURCHMESSER::text, '') ELSE '' END, ''
            ) ||
            COALESCE(
              CASE WHEN S.wandstaerke::numeric > 0 THEN ' x ' || COALESCE(S.wandstaerke::text, '') ELSE '' END, ''
            )
          END, ''
        ) ||
        COALESCE(
          CASE WHEN L.kurztext = 'HSB' THEN ' ' || COALESCE(L.langtext, '') ELSE '' END, ''
        )
      WHEN F.kurztext IN ('KR_SEL_MU', 'KR_SEL_RI') THEN
        COALESCE(M.langtext, '')
      ELSE
        COALESCE(
          CASE WHEN S.nennweite IS NOT NULL AND S.nennweite <> 0 THEN
            COALESCE(
              CASE
                WHEN F.kurztext IN ('KM_TRL','KR_DRL','KR_SIL','KR_SEL','KR_TRL','KR_VFL','KS_TRL') AND vtotal_length > 5 THEN
                  COALESCE(
                    CASE WHEN F.kurztext IN ('KR_DRL','KR_SIL') THEN substring(F.kurztext,4,2) || ' ' ELSE ' ' END, ''
                  ) ||
                  COALESCE(
                    CASE WHEN vtotal_length IS NOT NULL AND vtotal_length > 13 THEN
                      COALESCE(ROUND(vtotal_length,2)::text, '')::numeric || ' m ' ||
                      COALESCE(ROUND((S.ABLAUFHOEHE::numeric - S.EINLAUFHOEHE::numeric)/vtotal_length*1000,1)::text, '') || ' ‰ ' ||
                      COALESCE(M.kurztext, '') || ' DN ' || COALESCE(S.nennweite::text, '') ||
                      COALESCE(CASE WHEN L.kurztext = 'BV' THEN ' ' || COALESCE(L.langtext, '') ELSE '' END, '')
                    ELSE
                      COALESCE(M.kurztext, '') || ' DN ' || COALESCE(S.nennweite::text, '')
                    END, ''
                  )
                WHEN F.kurztext IN ('KM_GAL','KR_GAL','KS_GAL','GW','KR_DRGL','KR_SIGL') THEN
                  COALESCE(M.kurztext, '') ||
                  COALESCE(CASE WHEN S.nennweite::numeric > 0 THEN ' ' || COALESCE(S.nennweite::text, '') ELSE '' END, '')
              END, ''
            )
          END, ''
        )
    END, ''
  ) into tmp
FROM verundentsorgung.aw_lin_haltung S
LEFT JOIN verundentsorgung.st_vw_medium F ON S.id_st_vw_medium::uuid = F.id::uuid
LEFT JOIN verundentsorgung.st_vw_material M ON S.id_st_vw_material::uuid = M.id::uuid
LEFT JOIN verundentsorgung.st_vw_verlegetyp L ON S.id_st_vw_verlegetyp::uuid = L.id::uuid
WHERE F.kurztext IN (
  'KM_GAL','KM_TRL','KR_DRL','KR_GAL','KR_SEL','KR_TRL','KR_VFL','KS_GAL','KS_TRL',
  'ADL','ADL_GAL','VS_GAL','VS_TRL','GW','KR_SIL','KR_DRGL','KR_SIGL','RDL_GAL','RDL',
  'KR_SEL_MU','KR_SEL_RI'
)
AND S.id::uuid = vID::uuid;



    RETURN tmp;
END;
$$;


--
-- TOC entry 24682 (class 1255 OID 46620738)
-- Name: label_def_knoten(uuid); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_def_knoten(vid uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
vLabel text;
vTabelle text;
vTyp text;
vHydraulic text;
vSpalte text;
vSpalte1 text;
vAnz_Spalte text;
vAnz_Spalte1 text;
vSQL text;
begin
select 'aw_pkt_verbindungen' ,  m.kurztext , v.kurztext as typ
into vTabelle,  vHydraulic, vTyp
from verundentsorgung.aw_pkt_verbindungen t 
left join verundentsorgung.st_vw_medium m on m.id = t.id_st_vw_medium  
left join verundentsorgung.st_vw_verbindungstyp v on v.id = t.id_st_vw_verbindungstyp where t.id = vid;


--raise notice '%,%',vTabelle,vTyp;
if  vTabelle = 'aw_pkt_verbindungen' and vTyp in ( 'ENDK','MAROA','SCHRO' )  --and vHydraulic in ('ADL_GAK','ADL_K','VS_GAK','VS_TRK')
    then

				SELECT  CASE WHEN NAME_NUMBER like '%' AND ( ( OKG != 0 and OKG is not null ) and ( okr !=0 and okr is not null ) and ( sohlhoehe != 0 and sohlhoehe is not null ) ) THEN
		  /*1,2,3*/ NAME_NUMBER||'\'||'GH: '||OKG||'\'||'OKR:'||okr||'\'||'RS: '||sohlhoehe
		    /*1,2*/ WHEN NAME_NUMBER like '%' AND ( ( OKG != 0 and OKG is not null ) and ( okr !=0 and okr is not null ) and ( sohlhoehe  = 0  or sohlhoehe is     null ) ) THEN
		    /*1,2*/ NAME_NUMBER||'\'||'GH: '||OKG||'\'||'OKR:'||okr
		    /*1,3*/ WHEN NAME_NUMBER like '%' AND ( ( OKG != 0 and OKG is not null ) and ( okr  = 0  or okr is     null ) and  ( sohlhoehe != 0 and sohlhoehe is not null ) ) THEN
		    /*1,3*/ NAME_NUMBER||'\'||'GH: '||OKG||'\'||'RS: '||sohlhoehe
		    /*2,3*/ WHEN NAME_NUMBER like '%' AND ( ( OKG  = 0  or OKG is     null ) and ( okr != 0 and okr is not null ) and ( sohlhoehe != 0 and sohlhoehe is not null ) ) THEN
		    /*2,3*/ NAME_NUMBER||'\'||'OKR:'||okr||'\'||'RS: '||sohlhoehe
		    /*1  */ WHEN NAME_NUMBER like '%' AND ( ( OKG  != 0 and OKG is not null ) and ( okr = 0  or okr is     null ) and ( sohlhoehe  = 0  or sohlhoehe is     null ) ) THEN
		    /*1  */ NAME_NUMBER||'\'||'GH: '||OKG
		    /*2  */ WHEN NAME_NUMBER like '%' AND ( ( OKG   = 0 or OKG is     null ) and ( okr != 0 and okr is not null ) and ( sohlhoehe  = 0 or sohlhoehe is     null ) ) THEN
		    /*2  */ NAME_NUMBER||'\'||'OKR:'||okr
		    /*3  */ WHEN NAME_NUMBER like '%' AND ( ( OKG   = 0 or OKG is     null ) and ( okr  = 0 or okr is     null ) and ( sohlhoehe != 0 and sohlhoehe is not null ) ) THEN
		    /*3  */ NAME_NUMBER||'\'||'RS: '||sohlhoehe
		    else NAME_NUMBER
		      END into vLabel
		     from verundentsorgung.aw_pkt_verbindungen where id = vid;
------------------------------------------------------------------------------------------------     
  else
    vSpalte := 'sohlhoehe'; 
    vAnz_Spalte := 'RS'; 
vSQL := 'SELECT coalesce(CASE WHEN NAME_NUMBER like ''%'' AND ( ( OKG != 0 and OKG is not null ) OR ( '||vSpalte||' !=0 and '||vSpalte||' is not null ) ) THEN
            NAME_NUMBER||''\''
       else NAME_NUMBER
       END, '''') || 
       coalesce(CASE WHEN OKG != 0 AND '||vSpalte||' !=0 THEN
            ''GH: ''||OKG::numeric||''\''
            WHEN  OKG != 0 then
            ''GH: ''||OKG::numeric
       END,'''') ||
       coalesce(CASE WHEN  '||vSpalte||' !=0 THEN
       '''||vAnz_Spalte||': ''||'||vSpalte||'
      END,'''')
     from verundentsorgung.'||vTabelle ||' where id = '||''''||vID||'''';

EXECUTE  vSQL into vLabel;
------------------------------------------------------------------------------------------------ 
end if;
return vLabel::text;
end; $$;


--
-- TOC entry 24728 (class 1255 OID 52205714)
-- Name: label_erfassen(uuid, text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_erfassen(vid uuid, vname_number text, vtable text, vlabel_id text, vpoint1x text, vpoint1y text, vpoint2x text, vpoint2y text, vid_projekt uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
	vRETURN       text default 't';
	--vLabel_id        text default '10005';
	vLabel_regel	text;
	vLabel_text		text;
	vLayout			jsonb;
	vWinkel         numeric;
	vid_st_vw_projekt uuid;
	vid_st_vw_objektbezeichnung uuid;
	vschema         text;
BEGIN
    -- Get vtotal_length from your custom function
/*
kontzept
select label_id into vlabel_id from label_list where table_name = vtable;     

*/

select attributregel,id  into vLabel_Regel, vlabel_id from verundentsorgung.st_vw_label_definition where kurztext = vlabel_id and id_st_vw_projekt = vid_projekt;

select id into vid_st_vw_objektbezeichnung from verundentsorgung.st_vw_objektbezeichnung where langtext = vtable and id_st_vw_projekt = vid_projekt;

--raise notice '%',vLabel_Regel;

vLabel_Regel := replace(vLabel_Regel, '$id', '''' || vid::text || '''');

--raise notice '%',vLabel_Regel;

execute vLabel_regel into  vLabel_text;

--raise notice '%',vLabel_text;

EXECUTE format('SELECT layout,id_st_vw_projekt FROM verundentsorgung.%I WHERE id = $1 and id_st_vw_projekt = $2', vtable)
INTO vlayout, vid_st_vw_projekt
USING vid,vid_projekt;

IF vpoint1x::numeric = vpoint2x::numeric AND vpoint1y::numeric = vpoint2y::numeric THEN
    vWinkel := 0;  
ELSE
    SELECT degrees(ST_Azimuth(
        ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),
        ST_SetSRID(ST_MakePoint(vpoint2x::numeric, vpoint2y::numeric), 25833)
    )) - 90 + 360
    INTO vWinkel;
    vWinkel := COALESCE(vWinkel, 0);
END IF;

select left(vtable,2) into vschema;

--raise notice '%,%,%,%,%,%,%,%', vid,vid_st_vw_projekt,  ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),vLabel_text, vlayout, vWinkel, vLabel_id::uuid, vid_st_vw_objektbezeichnung ;

IF vLabel_text IS NULL THEN
    RETURN vReturn;
END IF;
if vschema = 'aw' then 
insert into verundentsorgung.aw_pkt_label (id_objekt,id_st_vw_projekt, geometry, labeltext, layout, drehwinkel, id_st_vw_label_definition, id_st_vw_objektbezeichnung) Values (vid,vid_st_vw_projekt,  ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),vLabel_text, vlayout, vWinkel, vLabel_id::uuid, vid_st_vw_objektbezeichnung );
end if;
if vschema = 'wa' then 
insert into verundentsorgung.wa_pkt_label (id_objekt,id_st_vw_projekt, geometry, labeltext, layout, drehwinkel, id_st_vw_label_definition, id_st_vw_objektbezeichnung) Values (vid,vid_st_vw_projekt,  ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),vLabel_text, vlayout, vWinkel, vLabel_id::uuid, vid_st_vw_objektbezeichnung );

end if;
if vschema = 'ta' then 
insert into verundentsorgung.ta_pkt_label (id_objekt,id_st_vw_projekt, geometry, labeltext, layout, drehwinkel, id_st_vw_label_definition, id_st_vw_objektbezeichnung) Values (vid,vid_st_vw_projekt,  ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),vLabel_text, vlayout, vWinkel, vLabel_id::uuid, vid_st_vw_objektbezeichnung );
end if;

if vschema = 'ka' then 
insert into verundentsorgung.ka_pkt_label (id_objekt,id_st_vw_projekt, geometry, labeltext, layout, drehwinkel, id_st_vw_label_definition, id_st_vw_objektbezeichnung) Values (vid,vid_st_vw_projekt,  ST_SetSRID(ST_MakePoint(vpoint1x::numeric, vpoint1y::numeric), 25833),vLabel_text, vlayout, vWinkel, vLabel_id::uuid, vid_st_vw_objektbezeichnung );
end if;


    RETURN vReturn;
END;
$_$;


--
-- TOC entry 24736 (class 1255 OID 52282338)
-- Name: label_schacht(uuid); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_schacht(vid uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_name TEXT := '';
    v_cover TEXT := '';
    v_input TEXT := '';
    v_output TEXT := '';
    v_bottom TEXT := '';
	v_s_h TEXT := '';
	v_s_a Text:= '';

    covers_record RECORD;
    ipipes_record RECORD;
    opipes_record RECORD;
	s_haltung_record RECORD;
	s_a_record RECORD;
BEGIN
    -- manhole info
    SELECT b.name_number || '\',
           'S:   ' || to_char(b.sohlhoehe, 'FM99999.00')
    INTO v_name, v_bottom
    FROM verundentsorgung.aw_pkt_schacht b
    WHERE b.id = vid;

    -- covers
    FOR covers_record IN
        SELECT 'D:   ' || ltrim(to_char(c.deckelhoehe, '99999.00')) || '\' AS name
        FROM verundentsorgung.aw_pkt_schachtdeckel c
        WHERE c.name_number_objekt||'\' = v_name
    LOOP
        v_cover := v_cover || covers_record.name;
    END LOOP;

    -- input pipes
    FOR ipipes_record IN
        SELECT 'E' || row_number() OVER () || ': ' || name AS name
        FROM (
            SELECT ltrim(to_char(s.ablaufhoehe, '99999.00')) || '\' AS name
            FROM verundentsorgung.aw_lin_haltung s
			left join verundentsorgung.st_vw_einlaufnummer e on e.id = s.id_st_vw_einlaufnummer
            WHERE split_part(s.knoten_unten, ',', 1)||'\' = v_name order by e.kurztext
        ) subq
        ORDER BY subq.name
    LOOP
        v_input := v_input || ipipes_record.name;
    END LOOP;

    FOR s_haltung_record IN
        SELECT 'E' || row_number() OVER () || ': ' || name AS name
        FROM (
            SELECT ltrim(to_char(s.einlaufhoehe , '99999.00')) || '\' AS name, e.kurztext 
            FROM verundentsorgung.aw_lin_haltung s
            left join verundentsorgung.st_vw_einlaufnummer e on e.id = s.id_st_vw_einlaufnummer 
            WHERE split_part(s.knoten_unten, ',', 1)||'\' = v_name order by e.kurztext
        ) subq
        ORDER BY subq.name
    LOOP
        v_s_h := v_s_h || s_haltung_record.name;
    END LOOP;

    -- output pipes
    FOR opipes_record IN
        SELECT 'A' || row_number() OVER () || ': ' || name AS name
        FROM (
            SELECT ltrim(to_char(s.sohle_einlaufschacht , '99999.00')) || '\' AS name, s.name_number 
            FROM verundentsorgung.aw_lin_haltung s
            WHERE split_part(s.knoten_oben, ',', 1)||'\' = v_name
        ) subq
        ORDER BY subq.name
    LOOP
        v_output := v_output || opipes_record.name;
    END LOOP;

    FOR s_a_record IN
        SELECT 'A' || row_number() OVER () || ': ' || name AS name
        FROM (
            SELECT ltrim(to_char(s.ablaufhoehe , '99999.00')) || '\' AS name, s.name_number 
            FROM verundentsorgung.aw_lin_haltung s
            WHERE split_part(s.knoten_oben, ',', 1)||'\' = v_name
        ) subq
        ORDER BY subq.name
    LOOP
        v_s_a := v_s_a || s_a_record.name;
    END LOOP;


    RETURN COALESCE(v_name, '') 
     || COALESCE(v_cover, '')
	 || COALESCE(v_s_h, '')
	 || COALESCE(v_s_a, '')
     --|| COALESCE(v_input, '') 
     --|| COALESCE(v_output, '') 
     || COALESCE(v_bottom, '');

END;
$$;


