-- TOC entry 24691 (class 1255 OID 47240095)
-- Name: label_update_test(uuid); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_update_test(vid_parent uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    vRETURN        text DEFAULT 't';
    vLabel_id      text DEFAULT '0';
    vLabel_Regel   text;
    vLabel_text    text;
    vLayout        jsonb;
    vWinkel        numeric;
    vid_label      uuid;
    vtable         text;
    rec            RECORD;
BEGIN

    FOR rec IN
        SELECT id, label_id, table_parent
        FROM verundentsorgung.aw_pkt_label_text
        WHERE id_parent = vid_parent
    LOOP
        -- Assign variables
        vid_label := rec.id;
        vLabel_id := rec.label_id;
        vtable    := rec.table_parent;

        RAISE NOTICE 'ID: %, Label ID: %, Table: %', vid_label, vLabel_id, vtable;

		

		select langtext into vtable from verundentsorgung.st_vw_objektbezeichnung where id = vtable::uuid;

        -- Get rule
        SELECT attributregel
        INTO vLabel_Regel
        FROM verundentsorgung.st_vw_label_definition
        WHERE kurztext = vLabel_id;

        IF vLabel_Regel IS NULL THEN
            RAISE NOTICE 'No rule found for label_id: %', vLabel_id;
            CONTINUE;
        END IF;

        -- Replace variable in SQL rule
        vLabel_Regel := replace(vLabel_Regel, '$id', quote_literal(vid_parent::text));
        RAISE NOTICE 'Executing rule: %', vLabel_Regel;

        -- Execute rule to get label text
        EXECUTE vLabel_Regel INTO vLabel_text;
        RAISE NOTICE 'Label text: %', vLabel_text;

        -- Get layout dynamically
        EXECUTE format('SELECT layout FROM verundentsorgung.%I WHERE id = $1', vtable)
        INTO vLayout
        USING vid_parent;

        -- Update the record
        UPDATE verundentsorgung.aw_pkt_label_text
        SET label_text = vLabel_text,
            layout = vLayout
        WHERE id = vid_label;
    END LOOP;

    RETURN vReturn;
END;
$_$;


--
-- TOC entry 24874 (class 1255 OID 56951416)
-- Name: label_update_wa(uuid, jsonb); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.label_update_wa(vid_objekt uuid, vlayout jsonb) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    vLabel_text   text;
    rec           RECORD;
BEGIN
	--raise notice '%',vid_objekt;
	--raise notice '%',vlayout;
    FOR rec IN
        SELECT
            l.id                         AS label_id,
            d.attributregel              AS label_regel,
			d.id                         as regel_id,
            o.langtext                   AS objekt_tabelle,
			replace(d.attributregel, '$id', quote_literal(l.id_objekt::text)) as Regel
        FROM verundentsorgung.wa_pkt_label l
        JOIN verundentsorgung.st_vw_label_definition d
            ON d.id = l.id_st_vw_label_definition
        JOIN verundentsorgung.st_vw_objektbezeichnung o
            ON o.id = l.id_st_vw_objektbezeichnung
        WHERE l.id_objekt = vid_objekt
    LOOP
raise notice '%',rec.regel_id;
if rec.regel = 'unbekannt' then return 'f'; end if ;

		execute rec.regel into  vLabel_text;
			--raise notice '%',rec.regel;
			--raise notice '%',vLabel_text;
		


		IF vLabel_text IS NULL THEN
    		RETURN 'f';
		END IF;

        
        UPDATE verundentsorgung.wa_pkt_label
        SET labeltext = vLabel_text,
            layout    = vLayout
        WHERE id = rec.label_id;
    END LOOP;

    RETURN 't';
END;
$_$;


