	COALESCE( ( select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_struckturbedingung     z where z.kurztext::text = q.struckturbedingung_s::text and id_st_vw_projekt= $1::uuid  ),    '''|| (select id::text from verundentsorgung.st_vw_struckturbedingung     where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ) ||'''::uuid)::uuid id_st_vw_struckturbedingung,

