vMIGRATIONTESTORT   text default 'Grevesmühlen';
vZgesamt      integer default 0;
vEXECUTE      text default '1';
begin
--
vSQL := 'select wert_text::text from "'||vZIELSCHEMA||'"."admin_projekt_parameter" where wert_aktivstatus = ''1'' and id_st_vw_projekt= $1 and kurztext = $2'; execute vSQL into vMIGRATIONTESTORT using vID_PROJEKT::uuid, 'migrationsort';
raise notice '%', concat('001. Migrationsort: ''', vscript_name, '''');
--
if vscript_name = 'migration_032_insert_wa_pkt_beprobung' then
raise notice '%', vscript_name;
--vQUELLSCHEMA  := 'bereitschaftsauskunft';
vZIELSCHEMA   := 'verundentsorgung';
--
vQUELLTABELLE := 'v_wa_beprobungspunkt_s';
vZIELTABELLE  := 'wa_pkt_beprobungspunkt'; 
--vSQL := 'insert into "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" ( id, ident_hist, amt, id_st_vw_projekt) ( select $1, $2, $3, $4 where not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" where id = $5 ) )';
--raise notice '%', vSQL; execute vSQL using vID_DEFAULT, vID_DEFAULT, vKURZTEXT_DEFAULT, vID_PROJEKT, vID_DEFAULT;
vSQL := 'delete from "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" where id_st_vw_projekt  in ( $1::uuid )';
raise notice '%', vSQL; execute vSQL using vid_projekt;
--CONSTRAINT uk1_st_amt UNIQUE (id_st_vw_projekt, amt),
--
--vSQL := 'select * from pg_tables where schemaname = $1 and left(tablename,5) like ''v_ww_'' order by tablename'; 
--for vRC_TABLES in vSQL using vQUELLSCHEMA loop
for vRC in (
select 'st_vw_betriebsstatus'        T, 'betriebsstatus'        C, 'langtext' ZF  union
select 'st_vw_lagestatus'            T, 'lagestatus'            C, 'langtext' ZF  union
select 'st_vw_material'              T, 'material'              C, 'langtext' ZF  union
