select 'st_vw_beprobung'               T, 'beprobung'                   C, 'langtext' ZF 
) loop
vSQL := ' insert into "'||vZIELSCHEMA||'"."'||vRC.T||'" ( ident_hist, kurztext, langtext, id_st_vw_projekt )
  select q.ident_hist, q.kurztext, q.langtext, q.id_st_vw_projekt from ( select  ''unbekannt'' ident_hist, ''unbekannt'' kurztext, ''unbekannt'' langtext, '''||vid_projekt||'''::uuid id_st_vw_projekt ) q
