vSQL := 'select count(*) z from information_schema.columns where table_schema = '''||vQUELLSCHEMA||''' and table_name = '''||vQUELLTABELLE||''' and column_name = '''||vRC.C||'''||''_s'' '; raise notice '%', concat('003b. vSQL: ', vSQL); execute vSQL into vZ2; -- using vQUELLSCHEMA, vQUELLTABELLE, vRC.C; --kurz (short)
