                    where not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vRC.T||'" i where i.kurztext = Q.kurztext and i.id_st_vw_projekt = Q.id_st_vw_projekt )
                       and lower( q.langtext::text ) not in (''unbekannt'')
              ';     raise notice '%', concat('004. vSQL: ', vSQL); if vEXECUTE = '1' then execute vSQL; end if;
end if;
if vZ1 = 0 and vZ2 = 1 then --langtext gibt es nicht, kurztext vorhanden
     vSQL := 
'insert into "'||vZIELSCHEMA||'"."'||vRC.T||'" ( kurztext, langtext, id_st_vw_projekt ) 
