                    where not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vRC.T||'" i where i.kurztext = Q.kurztext and i.id_st_vw_projekt = Q.id_st_vw_projekt )
                       and lower( q.kurztext::text ) not in (''unbekannt'')
              ';     raise notice '%', concat('005. vSQL: ', vSQL); if vEXECUTE = '1' then execute vSQL; end if;
end if;
if vZ1 = 1 and vZ2 = 1 then --langtext und kurztext vorhanden
     vSQL := '
insert into "'||vZIELSCHEMA||'"."'||vRC.T||'" ( kurztext, langtext, id_st_vw_projekt ) 
                select q.langtext, q.kurztext, q.id_st_vw_projekt from
