                      and not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vRC.T||'" i where i.langtext = Q.langtext and i.id_st_vw_projekt = Q.id_st_vw_projekt )
                      and lower( q.kurztext::text ) not in (''unbekannt'')
                      and lower( q.langtext::text ) not in (''unbekannt'')
              ';     raise notice '%', concat('006. vSQL: ', vSQL); if vEXECUTE = '1' then execute vSQL; end if;
end if; --if vZ1 = 1 and vZ2 = 1 then --langtext und kurztext vorhanden
--
end loop;
--
vSQL := concat('select count(*) from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" where ort like ( concat(''%'',''',vMIGRATIONTESTORT,''',''%'') )'); 
raise notice '%', concat('007. vSQL: ', vSQL); if vEXECUTE = '1' then execute vSQL into vZgesamt; end if; raise notice '%', concat('008. Anzahl zu migrierender DS für ', vMIGRATIONTESTORT, ' : ', vZgesamt::text);
--
vSQL := concat('select * from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" where name_number like ''%'' and ort like ( concat(''%'',''', vMIGRATIONTESTORT, ''',''%'') ) order by amt, gemeinde, ort, strasse, name_number'); 
for vRC in execute VSQL loop --using vMIGRATIONTESTORT loop
vZ := vZ + 1; raise notice '%', concat('Datensatz: ', vZ::text, ' von ', vZgesamt::text, ', name_number: ', vRC.name_number, ', ', vZIELSCHEMA, '.', vZIELTABELLE, ', ', vID_PROJEKT );
if ((vZ::int::numeric / 1000::numeric) - FLOOR(vZ::int::numeric / 1000::numeric)::numeric)::numeric = 0::numeric then raise notice '%', 'commit'; commit; end if;
--''', (select id::text from verundentsorgung.st_vw_betriebsstatus where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''
