	id_st_vw_betriebsstatus,    -- text DEFAULT ''00000000-0000-0000-0000-000000000000''::text NOT NULL,
	id_st_vw_medium,            -- text DEFAULT ''00000000-0000-0000-0000-000000000000''::text NOT NULL,
    --baujahr,                  --int
	id_st_vw_beprobung,
	gps_koordinate,
	google_maps_link
    ) '||'
   select
	fido::text             , --001 numeric(10) NULL,
