    ''unbekannt''::text    , --007 leistungsobjektnummer 
    --ogc_fid serial4 NOT NULL,
	--kanio_id text(266) NULL,
	--kanio_entw text(13) NULL,
	--COALESCE(knoten_oben::text, ''00000000-0000-0000-0000-000000000000'')::text      , --008 text(30) NULL,
	--COALESCE(knoten_unten::text, ''00000000-0000-0000-0000-000000000000'')::text     , --009  text(30) NULL,
	"bemerkung", --COALESCE(bemerkung::text, ''noch keine Bemerkung'')::text  , --010 text(2000) NULL,
    --case when bemerkung is null then ''noch keine Bemerkung'' else bemerkung end, 
--
    (COALESCE((select i.id_st_strasse from verundentsorgung.strassenschluessel_v i where 
       i.id_st_vw_projekt = '''||vID_PROJEKT||'''::uuid                                                                      and 
       coalesce(replace(replace(replace(i.gemeinde,'','','' ''),'''','' ''),''  '','' ''),''nicht zugewiesen'') = q.gemeinde and 
