       coalesce(replace(replace(replace(i.strasse,'','','' ''),'''','' ''),''  '','' ''),''nicht zugewiesen'')  = q.strasse
              )::text, ''', (select id from verundentsorgung.st_strasse where strasse = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::text))::uuid id_st_strasse,
--
	wkb_geometry                                  , --012 public.geometry(geometry, 25833) NULL,
	--COALESCE(hnr::text, ''unbekannt'')::text       , --013 text(30) NULL,
	--COALESCE(zhnr::text, ''unbekannt'')::text , --014 text(30) NULL,
	--hausnr_zusatz text(60) NULL,
	COALESCE(lagezusatz::text, ''unbekannt'')::text       , --015 text(255) NULL,
    $1::uuid             id_st_vw_projekt, 
    COALESCE( ( select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_betriebsstatus z where z.kurztext::text = q.betriebsstatus_s::text and id_st_vw_projekt= $1::uuid  ),     ''', (select id::text from verundentsorgung.st_vw_betriebsstatus where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::uuid)::uuid id_st_vw_betriebsstatus,
    COALESCE( ( select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_medium         z where z.langtext::text = q.medium::text and id_st_vw_projekt= $1::uuid  ),     ''', (select id::text from verundentsorgung.st_vw_medium where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::uuid)::uuid id_st_vw_medium,
    --case when baujahr is null or baujahr < 1800 or baujahr > 2050 then 1900 else baujahr end baujahr, --numeric(4) NULL
	COALESCE( ( select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_beprobung     z where z.kurztext::text = q.beprobung_s::text and id_st_vw_projekt= $1::uuid  ),     ''', (select id::text from verundentsorgung.st_vw_beprobung where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::uuid)::uuid id_st_vw_beprobung,
	gps_koordinate,
	google_maps_link
   from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" q
     where q.ogc_fid = $2 
       --and not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" z where z.fid_hist = q.fido::text )
       --and st_asText(ST_LineMerge(q.wkb_geometry)) not like (''MULTILINESTRING%'') 
             ');
    --raise notice '%', vSQL; 
