--
--vSQL := 'select * from pg_tables where schemaname = $1 and left(tablename,5) like ''v_ww_'' order by tablename'; 
--for vRC_TABLES in vSQL using vQUELLSCHEMA loop

--
vSQL := 'select count(*) from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" where table_schema = ''SONSTIGE'' and label_text is not null and wkb_geometry is not null  '; execute vSQL into vZ; raise notice '%', concat('Es werden ', vZ::text, ' Datensätze abgerufen.');
vSQL := 'select * from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'"        where table_schema = ''SONSTIGE'' and label_text is not null and wkb_geometry is not null  '; raise notice '%', vSQL;
for vRC in execute VSQL loop
vZ1 := vZ1 + 1; raise notice '%', concat(vZ1::text, ' von ', vZ::text);
--vNAME_NUMBER_SUFFIX := vNAME_NUMBER_SUFFIX + 1;
vSQL := concat('insert into "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'"
 (	id_st_vw_label_definition,
	id_objekt,
	labeltext,
	drehwinkel ,
    id_st_vw_projekt,
	geometry,
id_st_vw_objektbezeichnung
 ) '||'
select
 COALESCE( ( select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_label_definition    z where z.kurztext::text = q.label_def_id::text and id_st_vw_projekt= $1::uuid  ),     ''', (select id::text from verundentsorgung.st_vw_label_definition where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::uuid)::uuid id_st_vw_label_definition,
 case 
 when table_name = ''NETZ_TBL''       then (select aw.id::uuid from "'||vQUELLSCHEMA||'".tbl_union_v z, verundentsorgung.ta_lin_netz aw        where z.table_schema = ''SONSTIGE'' and z.label_text is not null and z.wkb_geometry is not null and z.fid_parent::text = aw.fid_hist::text and aw.id_st_vw_projekt::text = $1::text and ogc_fid = $2 )
 when table_name = ''NETZKNOTEN_TBL'' then (select aw.id::uuid from "'||vQUELLSCHEMA||'".tbl_union_v z, verundentsorgung.ta_pkt_netzknoten aw  where z.table_schema = ''SONSTIGE'' and z.label_text is not null and z.wkb_geometry is not null and z.fid_parent::text = aw.fid_hist::text and aw.id_st_vw_projekt::text = $1::text and ogc_fid = $2 )
 else null
 end as id_parent,
 label_text,
--case when q.table_name = ''NETZKNOTEN_TBL'' then winkel
--		 --when q.table_name = ''NETZ_TBL'' then winkel
--		 else orientation end as winkel	 ,
orientation,
 $1::uuid id_st_vw_projekt, 
 wkb_geometry ,
 COALESCE( (  select z.id::uuid from "'||vZIELSCHEMA||'".st_vw_objektbezeichnung    z where z.langtext::text = ( case 
 when q.table_name = ''NETZ_TBL'' then ''ta_pkt_netzknoten''
 when q.table_name = ''NETZKNOTEN_TBL'' then ''ta_lin_netz''
 else q.table_name
 end 
) and z.id_st_vw_projekt::text = $1::text ),         ''', ( select id::text from verundentsorgung.st_vw_objektbezeichnung where kurztext = 'unbekannt' and id_st_vw_projekt = vID_PROJEKT::uuid ), '''::uuid) id_st_vw_objektbezeichnung
--fid_parent
   from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" q
     where   ogc_fid = $2
		     and wkb_geometry is not null
			and label_text is not null
       ');
    raise notice '%', vRC.ogc_fid; 
	--raise notice '%', vsql;
    execute vSQL using vID_PROJEKT, vRC.ogc_fid; --, vMIGRATIONTESTORT;
   end loop;
   end if; --if vscript_name = 'migration_054_insert_ta_pkt_label' then

end; $_$;


