    a.zieltabelle
   FROM ( SELECT q.ogc_fid,
            q.kanio_id,
            q.schemaname,
            q.ident_hist,
            q.author,
            q.commentary,
            q.creationdate,
            q.fid_parent,
            q.filename,
            q.title,
