            q.objekt_vorhanden,
            q.id,
            q.name_number,
            q.wkb_geometry,
            q.id_suche,
            q.dbschema,
            q.fid,
            q.fido,
            q.hydraulic_function_s,
            q.synctime,
            q.anz_dokumente,
            q.datei_name,
            q.datei_pfad,
            q.datei_mimetyp,
            q.datei_inhalt,
            q.objekt_tabelle_schema,
            q.gemeinde_schluessel,
            concat(q.schemaname, ''.'', q.f_class_name) AS quelltabelle,
                CASE
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''DIENSTBARKEITEN13.DIENSTBARKEITEN''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KABEL.NETZ''::text THEN ''bereitschaftsauskunft.v_netz_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KABEL.NETZKNOTEN''::text THEN ''bereitschaftsauskunft.v_netzknoten_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KOORDINATENRASTER.GITTER''::text THEN ''bereitschaftsauskunft.v_gi_gitter_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''SONSTIGE.NETZ''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.UMLAGEFLAECHEN''::text THEN ''bereitschaftsauskunft.v_umlageflaechen''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_BASIN''::text THEN ''bereitschaftsauskunft.v_ww_basin_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_COALESCENCE_SEP''::text THEN ''bereitschaftsauskunft.v_ww_coalescence_sep_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DAMAGE''::text THEN ''bereitschaftsauskunft.v_ww_damage_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DETENTION_FACILITY''::text THEN ''bereitschaftsauskunft.v_ww_detention_facility_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DISCHARGE''::text THEN ''bereitschaftsauskunft.v_ww_discharge_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_FITTING''::text THEN ''bereitschaftsauskunft.v_ww_fitting_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_INTERMEDIATE_POINT''::text THEN ''bereitschaftsauskunft.v_ww_intermediate_point_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_MANHOLE''::text THEN ''bereitschaftsauskunft.v_ww_manhole_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_MISC_PLANT''::text THEN ''bereitschaftsauskunft.v_ww_misc_plant_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_OUTFALL''::text THEN ''bereitschaftsauskunft.v_ww_outfall_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_PUMP''::text THEN ''bereitschaftsauskunft.v_ww_pump_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_RESTRICTOR''::text THEN ''bereitschaftsauskunft.v_ww_restrictor_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SECTION''::text THEN ''bereitschaftsauskunft.v_ww_section_s_concat''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SEPTIC_TANK''::text THEN ''bereitschaftsauskunft.v_ww_septic_tank_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SPUEHLHYDRANT''::text THEN ''bereitschaftsauskunft.v_ww_spuehlhydrant_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_TREATMENT_PLANT''::text THEN ''bereitschaftsauskunft.v_ww_treatment_plant_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_VALVE''::text THEN ''bereitschaftsauskunft.v_ww_valve_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.ANALOGKARTEN''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.GG_DRUCKSTATION''::text THEN ''bereitschaftsauskunft.v_gg_druckstation_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.SG_WASSERWERK''::text THEN ''bereitschaftsauskunft.v_sg_wasserwerk_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_ARMATURE''::text THEN ''bereitschaftsauskunft.v_wa_armature_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_COVER''::text THEN ''bereitschaftsauskunft.v_wa_cover_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_DAMAGE''::text THEN ''bereitschaftsauskunft.v_wa_damage_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_FITTING''::text THEN ''bereitschaftsauskunft.v_wa_fitting_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HOUSE_CONNECTOR''::text THEN ''bereitschaftsauskunft.v_wa_house_connector_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HYDRANT''::text THEN ''bereitschaftsauskunft.v_wa_hydrant_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MANHOLE''::text THEN ''bereitschaftsauskunft.v_wa_manhole_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MARKER''::text THEN ''bereitschaftsauskunft.v_wa_marker_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_METER''::text THEN ''bereitschaftsauskunft.v_wa_meter_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PIPE''::text THEN ''bereitschaftsauskunft.v_wa_pipe_s_concat''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PRESSURE_REDUCTION''::text THEN ''bereitschaftsauskunft.v_wa_pressure_reduction_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_SOURCE''::text THEN ''bereitschaftsauskunft.v_wa_source_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_TANK''::text THEN ''bereitschaftsauskunft.v_wa_tank_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VALVE''::text THEN ''bereitschaftsauskunft.v_wa_valve_s''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VENT''::text THEN ''bereitschaftsauskunft.v_wa_vent_s''::text
                    ELSE NULL::text
                END AS quellview,
                CASE
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''DIENSTBARKEITEN13.DIENSTBARKEITEN''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KABEL.NETZ''::text THEN ''verundentsorgung.ka_lin_kabelnetz''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KABEL.NETZKNOTEN''::text THEN ''verundentsorgung.ka_pkt_kabelnetzknoten''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''KOORDINATENRASTER.GITTER''::text THEN ''verundentsorgung.al_fla_koordinatenraster''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''SONSTIGE.NETZ''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.UMLAGEFLAECHEN''::text THEN ''verundentsorgung.aw_fla_umlageflaeche''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_BASIN''::text THEN ''verundentsorgung.aw_pkt_becken''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_COALESCENCE_SEP''::text THEN ''verundentsorgung.aw_pkt_abscheider''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DAMAGE''::text THEN ''verundentsorgung.aw_pkt_abwasserschaden''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DETENTION_FACILITY''::text THEN ''verundentsorgung.aw_pkt_loeschwasserentnahmestelle''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_DISCHARGE''::text THEN ''verundentsorgung.aw_pkt_einleitungsstellen''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_FITTING''::text THEN ''verundentsorgung.aw_pkt_verbindungen''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_INTERMEDIATE_POINT''::text THEN ''verundentsorgung.aw_pkt_zwischenpunkt''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_MANHOLE''::text THEN ''verundentsorgung.aw_pkt_schacht''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_MISC_PLANT''::text THEN ''verundentsorgung.aw_pkt_sonstige_anlage''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_OUTFALL''::text THEN ''verundentsorgung.aw_pkt_auslauf''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_PUMP''::text THEN ''verundentsorgung.aw_pkt_pumpwerk''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_RESTRICTOR''::text THEN ''verundentsorgung.aw_pkt_dueker''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SECTION''::text THEN ''verundentsorgung.aw_lin_haltung''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SEPTIC_TANK''::text THEN ''verundentsorgung.aw_pkt_klaertank''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SPUEHLHYDRANT''::text THEN ''verundentsorgung.aw_pkt_spuehlhydrant''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_TREATMENT_PLANT''::text THEN ''verundentsorgung.aw_pkt_klaeranlage''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_VALVE''::text THEN ''verundentsorgung.aw_pkt_schieber''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.ANALOGKARTEN''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.GG_DRUCKSTATION''::text THEN ''verundentsorgung.wa_pkt_druckstation''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.SG_WASSERWERK''::text THEN ''verundentsorgung.wa_pkt_wasserwerk''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_ARMATURE''::text THEN ''verundentsorgung.wa_pkt_armatur''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_COVER''::text THEN ''verundentsorgung.wa_pkt_schachtdeckel''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_DAMAGE''::text THEN ''verundentsorgung.wa_pkt_wasserschaden''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_FITTING''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HOUSE_CONNECTOR''::text THEN ''verundentsorgung.wa_pkt_hausanschlusspunkt''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HYDRANT''::text THEN ''verundentsorgung.wa_pkt_hydrant''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MANHOLE''::text THEN ''verundentsorgung.wa_pkt_schacht''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MARKER''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_METER''::text THEN ''verundentsorgung.wa_pkt_wasserzaehler''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PIPE''::text THEN ''verundentsorgung.wa_lin_wasserleitung''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PRESSURE_REDUCTION''::text THEN ''verundentsorgung.wa_pkt_druckminderer''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_SOURCE''::text THEN ''verundentsorgung.wa_pkt_brunnen''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_TANK''::text THEN ''verundentsorgung.wa_pkt_behaelter''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VALVE''::text THEN ''verundentsorgung.wa_pkt_armatur''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VENT''::text THEN ''verundentsorgung.wa_pkt_entlueftung''::text
                    ELSE NULL::text
                END AS zieltabelle
           FROM bereitschaftsauskunft.tb_feature_document_gisz q) a 
           where schemaname in (''KABEL'', ''WW_DE'', ''ZVG_TW'') 
             and quelltabelle not like ''%ANALOG%'' 
             and quelltabelle not like ''%DIENST%''
             and zieltabelle like ''verundentsorgung.%''
  ORDER BY a.f_class_name'; --raise notice '%', vSQL;
--
execute concat('select count(*) from (', vSQL, ') a') into vZ1 using 'ZVG_TW';
raise notice '%',  concat( 'vZ1: ', vZ1);
--
for vRC in execute vSQL loop -- using 'ZVG_TW' loop
vZ2 := vZ2 + 1;
raise notice '%',  concat( vZ2::text, ' von ', vZ1::text );
raise notice '%',  concat( 'Quelle: ', vRC.quellview );
raise notice '%',  concat( 'Ziel: ', vRC.zieltabelle );
raise notice '%',  concat( 'vRC.name_number: ', vRC.name_number );
raise notice '%',  concat( 'vRC.fid_parent: ', vRC.fid_parent::text );
raise notice '%',  concat( 'vid_projekt: ', vid_projekt::text );
--
--vSQL := 'select count(*) from information_schema.tables where concat(table_schema, ''.'', table_name) = $1';
--         raise notice '%', vSQL;
 --        execute vSQL into vZ using vRC.zieltabelle;
--if vZ > 0 then
if 1 = 2 then
vSQL := 'select id_st_dokument from '||vZIELSCHEMA||'.st_dokument2objekt where ( id_objekt, id_st_vw_projekt ) in ( select id, id_st_vw_projekt from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2 )'; --verundentsorgung.wa_pkt_druckstation
         raise notice '%', vSQL; 
         raise notice '%',  concat('vRC.fid_parent: ', vRC.fid_parent::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL into vid_st_dokument using vRC.fid_parent::text, vid_projekt::uuid;
--
vSQL := 'delete                from '||vZIELSCHEMA||'.st_dokument2objekt where ( id_objekt, id_st_vw_projekt ) in ( select id, id_st_vw_projekt from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2 )'; --verundentsorgung.wa_pkt_druckstation
         raise notice '%', vSQL;
         raise notice '%', concat('vRC.fid_parent: ', vRC.fid_parent::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL using vRC.fid_parent::text, vid_projekt::uuid;
--
vSQL := 'delete                from '||vZIELSCHEMA||'.st_dokument        where id = $1 and id_st_vw_projekt = $2';
         raise notice '%', vSQL; 
         raise notice '%', concat('vid_st_dokument: ', vid_st_dokument::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL using vid_st_dokument, vid_projekt::uuid;
end if; --if 1 = 2 then 
--end if; --if vZ > 0 then
--
vid_st_dokument := gen_random_uuid();
--id des Objektes ermitteln.
vid_object := null;
vSQL := 'select id from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2';
execute vSQL into vid_object using vRC.fid_parent::text, vid_projekt::uuid;


if vid_object is not null then --nur wenn es das Objekt gibt, sonst macht es keinen Sinn
--
raise notice '%', '--';
raise notice '%', concat('insert into '||vZIELSCHEMA||'.st_dokument mit vid_st_dokument = ''', vid_st_dokument::text, ''', vid_object = ''', vid_object::text, '''');
raise notice '%', '--';
--
vSQL := 'insert into '||vZIELSCHEMA||'.st_dokument (
             id
           --, gueltig_von
           --, gueltig_bis
           , angelegt_am
           , angelegt_von
           , geaendert_am
           , geaendert_von
           , bemerkung
           , id_objekt
           , ident_hist
           , ident_object_hist
           , titel
           , kommentar
           , datei
           , id_st_vw_dokumenttyp
           , id_st_vw_projekt
           , id_st_vw_objektbezeichnung ) --values 
          select
             $1 --id
           --, gueltig_von
           --, gueltig_bis
           , $2 --angelegt_am
           , case when $3 is null then ''unbekannt'' else $3 end --angelegt_von
           , $4 --geaendert_am
           , case when $5 is null then ''unbekannt'' else $5 end --geaendert_von
           , $6 --bemerkung
           , $7 --id_objekt
           , $8 --ident_hist
           , $9 --ident_object_hist
           , case when $10 is null then ''unbekannt'' else $10 end --titel
           , case when $11 is null then ''unbekannt'' else $11 end --kommentar
           , case when $12 is null then ''unbekannt'' else $12 end --datei
           , $13 --id_st_vw_dokumenttyp
           , $14 --id_st_vw_projekt
           , $15 --id_st_vw_objektbezeichnung
          where not exists (select ''X'' from '||vZIELSCHEMA||'.st_dokument where id_objekt = $7 and datei = $12 and id_st_vw_projekt = $14 )
          RETURNING id        
';
--raise notice '%', concat('vid_object: ', vid_object::text);
execute vSQL into vid_st_dokument_returning using vid_st_dokument::uuid, vRC.sg_insrtdat, vRC.sg_insrtuser, vRC.sg_updtdat,  vRC.sg_updtuser, vRC.commentary 
                 , vid_object::uuid, vRC.fid_parent::text, vRC.fid_parent::text, vRC.title, vRC.commentary, vRC.filename::text
                 , '00000000-0000-0000-0000-000000000000'::uuid, vid_projekt::uuid, '00000000-0000-0000-0000-000000000000'::uuid   ;
raise notice '%', concat('vid_st_dokument_returning = ''', vid_st_dokument_returning::text, '''');
vSQL := 'select count(*) from '||vZIELSCHEMA||'.st_dokument where id = $1';
         execute vSQL into vZ3 using vid_st_dokument::uuid; 
         raise notice '%', concat('vZ3 = ''', vZ3::text, '''');
vSQL := 'insert into '||vZIELSCHEMA||'.st_dokument2objekt (
             angelegt_am
           , angelegt_von
           , geaendert_am
           , geaendert_von
           , bemerkung
           , id_st_dokument
           , id_objekt
           , id_st_vw_projekt 
           )
          select 
             $1 --angelegt_am
           , case when $2 is null then ''unbekannt'' else $2 end --angelegt_von
           , $3 --geaendert_am
           , case when $4 is null then ''unbekannt'' else $4 end --geaendert_von
           , $5 --bemerkung
           , $6 --id_st_dokument
           , $7 --id_objekt
           , $8 --id_st_vw_projekt 
          where not exists 
            (select ''X'' from '||vZIELSCHEMA||'.st_dokument2objekt 
               where id_objekt = $7 
                 and id_st_dokument= $6 
                 and id_st_vw_projekt = $8 )
                and exists 
             (select ''X'' from '||vZIELSCHEMA||'.st_dokument 
                where id_st_vw_projekt = $8 
                  and id               = $6 )';
raise notice '%', '--';
raise notice '%', concat('insert into '||vZIELSCHEMA||'.st_dokument2objekt mit vid_st_dokument = ''', vid_st_dokument::text
                          , ''', vid_object = ''', vid_object::text, '''');
raise notice '%', '--';

execute vSQL using vRC.sg_insrtdat, vRC.sg_insrtuser::text, vRC.sg_updtdat,  vRC.sg_updtuser::text
                 , concat(vRC.quelltabelle, ', ', vRC.zieltabelle, ', ', vRC.fid_parent::text)::text
                 , vid_st_dokument::uuid
                 , vid_object::uuid
                 , vid_projekt::uuid;
--
end if; --if vid_object is not null then

end loop;

