--Anfang Bereinigung
delete from verundentsorgung.st_dokument2objekt where id_st_dokument::text in (
select max(id::text) id /*, id_objekt, id_st_vw_projekt, 
case
--
  WHEN position('\\GiSFILE-sv02\O\'::text in datei::text ) > 0 THEN replace(replace(datei::text,'\'::text, '/'::text), '//GiSFILE-sv02/O/'::text, '/dokumente/O/'::text) --else datei
--
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.20.1.95/ARCHIV/%'::text                                                                  THEN replace(upper(btrim(datei::text)), 'HTTP://172.20.1.95/ARCHIV/'::text, '/dokumente/ARCHIV/'::text)
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.19.1.248/OEFFENTLICH/KANIO/INTERN/DOCUMENTS/DEPOT/%'::text                               THEN lower(replace(upper(btrim(datei::text)), 'HTTP://172.19.1.248/OEFFENTLICH/KANIO/INTERN/DOCUMENTS/DEPOT/'::text, '/dokumente/depot/'::text))
--
  --WHEN upper(btrim(datei::text)) ~~ 'HTTP://VM-KANIO-SV03:8060/CUSTOMDATA/INTERN/DOCUMENTS/DEPOT/%'::text                                THEN lower(replace(upper(btrim(datei::text)), 'HTTP://VM-kanio-sv03:8060/CustomData/intern/Documents/depot'::text, '/dokumente/depot/'::text))
--
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.19.1.223/ANLAGEN_DOKUMENTATION/%'::text                                                  THEN replace(upper(btrim(datei::text)), 'HTTP://172.19.1.223/ANLAGEN_DOKUMENTATION/'::text, '/dokumente/Anlagen_Dokumentation/'::text)
  WHEN upper(replace(btrim(datei::text), '\'::text, '/'::text)) ~~ 'HTTP://172.19.1.222/DIENSTBARKEITEN-GRUND/%'::text                   THEN replace(upper(btrim(datei::text)), 'HTTP://172.19.1.222/DIENSTBARKEITEN-GRUND/'::text, '/dokumente/Dokumentenablage/'::text)
  WHEN upper(replace(btrim(datei::text), '\'::text, '/'::text)) ~~ 'HTTP://VM-ZVGK-SV01/DIENSTBARKEITEN-GRUND/%'::text                   THEN replace(upper(btrim(datei::text)), 'HTTP:\\VM-ZVGK-SV01\DIENSTBARKEITEN-GRUND\'::text, '/dokumente/Dokumentenablage/'::text)
  when upper(replace(btrim(datei::text), '\'::text, '/'::text)) ~~ 'HTTP://VM-KANIO-SV03:8060/CUSTOMDATA/INTERN/DOCUMENTS/DEPOT/%'::text then replace(upper(btrim(datei::text)), 'HTTP://VM-KANIO-SV03:8060/CUSTOMDATA/INTERN/DOCUMENTS/DEPOT/'::text, '/dokumente/depot/'::text)
  --replace(upper(datei)::text, 'HTTP://VM-KANIO-SV03:8060/CUSTOMDATA/INTERN/DOCUMENTS/DEPOT/'::text, '/dokumente/depot/'::text)
  ELSE btrim(datei::text) end datei */
from verundentsorgung.st_dokument 
  where (id_objekt, id_st_vw_projekt, 
 case
--
  WHEN position('\\GiSFILE-sv02\O\'::text in datei::text ) > 0 THEN replace(replace(datei::text,'\'::text, '/'::text), '//GiSFILE-sv02/O/'::text, '/dokumente/O/'::text) --else datei
--
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.20.1.95/ARCHIV/%'::text                                                                  THEN replace(upper(btrim(datei::text)), 'HTTP://172.20.1.95/ARCHIV/'::text, '/dokumente/ARCHIV/'::text)
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.19.1.248/OEFFENTLICH/KANIO/INTERN/DOCUMENTS/DEPOT/%'::text                               THEN lower(replace(upper(btrim(datei::text)), 'HTTP://172.19.1.248/OEFFENTLICH/KANIO/INTERN/DOCUMENTS/DEPOT/'::text, '/dokumente/depot/'::text))
--
  --WHEN upper(btrim(datei::text)) ~~ 'HTTP://VM-KANIO-SV03:8060/CUSTOMDATA/INTERN/DOCUMENTS/DEPOT/%'::text                                THEN lower(replace(upper(btrim(datei::text)), 'HTTP://VM-kanio-sv03:8060/CustomData/intern/Documents/depot'::text, '/dokumente/depot/'::text))
--
  WHEN upper(btrim(datei::text)) ~~ 'HTTP://172.19.1.223/ANLAGEN_DOKUMENTATION/%'::text                                                  THEN replace(upper(btrim(datei::text)), 'HTTP://172.19.1.223/ANLAGEN_DOKUMENTATION/'::text, '/dokumente/Anlagen_Dokumentation/'::text)
  WHEN upper(replace(btrim(datei::text), '\'::text, '/'::text)) ~~ 'HTTP://172.19.1.222/DIENSTBARKEITEN-GRUND/%'::text                   THEN replace(upper(btrim(datei::text)), 'HTTP://172.19.1.222/DIENSTBARKEITEN-GRUND/'::text, '/dokumente/Dokumentenablage/'::text)
