vSQL := 'select wert_text::text from "'||vZIELSCHEMA||'"."admin_projekt_parameter" where wert_aktivstatus = ''1'' and id_st_vw_projekt= $1 and kurztext = $2'; execute vSQL into vMIGRATIONTESTORT using vID_PROJEKT::uuid, 'migrationsort';
raise notice '%', concat('001. Migrationsort: ''', vscript_name, '''');
--
