                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SECTION''::text THEN ''verundentsorgung.aw_lin_haltung''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SEPTIC_TANK''::text THEN ''verundentsorgung.aw_pkt_klaertank''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_SPUEHLHYDRANT''::text THEN ''verundentsorgung.aw_pkt_spuehlhydrant''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_TREATMENT_PLANT''::text THEN ''verundentsorgung.aw_pkt_klaeranlage''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''WW_DE.WW_VALVE''::text THEN ''verundentsorgung.aw_pkt_schieber''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.ANALOGKARTEN''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.GG_DRUCKSTATION''::text THEN ''verundentsorgung.wa_pkt_druckstation''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.SG_WASSERWERK''::text THEN ''verundentsorgung.wa_pkt_wasserwerk''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_ARMATURE''::text THEN ''verundentsorgung.wa_pkt_armatur''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_COVER''::text THEN ''verundentsorgung.wa_pkt_schachtdeckel''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_DAMAGE''::text THEN ''verundentsorgung.wa_pkt_wasserschaden''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_FITTING''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HOUSE_CONNECTOR''::text THEN ''verundentsorgung.wa_pkt_hausanschlusspunkt''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_HYDRANT''::text THEN ''verundentsorgung.wa_pkt_hydrant''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MANHOLE''::text THEN ''verundentsorgung.wa_pkt_schacht''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_MARKER''::text THEN ''''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_METER''::text THEN ''verundentsorgung.wa_pkt_wasserzaehler''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PIPE''::text THEN ''verundentsorgung.wa_lin_wasserleitung''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_PRESSURE_REDUCTION''::text THEN ''verundentsorgung.wa_pkt_druckminderer''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_SOURCE''::text THEN ''verundentsorgung.wa_pkt_brunnen''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_TANK''::text THEN ''verundentsorgung.wa_pkt_behaelter''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VALVE''::text THEN ''verundentsorgung.wa_pkt_armatur''::text
                    WHEN concat(q.schemaname, ''.'', q.f_class_name) = ''ZVG_TW.WA_VENT''::text THEN ''verundentsorgung.wa_pkt_entlueftung''::text
                    ELSE NULL::text
                END AS zieltabelle
           FROM "'||vQUELLSCHEMA||'".tb_feature_document_gisz q) a 
           where schemaname in (''KOORDINATENRASTER'') --(''KABEL'', ''WW_DE'', ''ZVG_TW'') 
             and quelltabelle not like ''%ANALOG%'' 
             and quelltabelle not like ''%DIENST%''
             and zieltabelle like ''verundentsorgung.%''
  ORDER BY a.f_class_name'; --raise notice '%', vSQL;
--
execute concat('select count(*) from (', vSQL, ') a') into vZ1 using 'ZVG_TW';
raise notice '%',  concat( 'vZ1: ', vZ1);
--
for vRC in execute vSQL loop -- using 'ZVG_TW' loop
vZ2 := vZ2 + 1;
raise notice '%',  concat( vZ2::text, ' von ', vZ1::text );
raise notice '%',  concat( 'Quelle: ', vRC.quellview );
raise notice '%',  concat( 'Ziel: ', vRC.zieltabelle );
raise notice '%',  concat( 'vRC.name_number: ', vRC.name_number );
raise notice '%',  concat( 'vRC.fid_parent: ', vRC.fid_parent::text );
raise notice '%',  concat( 'vid_projekt: ', vid_projekt::text );
--
--vSQL := 'select count(*) from information_schema.tables where concat(table_schema, ''.'', table_name) = $1';
--         raise notice '%', vSQL;
 --        execute vSQL into vZ using vRC.zieltabelle;
--if vZ > 0 then
if 1 = 2 then
vSQL := 'select id_st_dokument from '||vZIELSCHEMA||'.st_dokument2objekt where ( id_objekt, id_st_vw_projekt ) in ( select id, id_st_vw_projekt from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2 )'; --verundentsorgung.wa_pkt_druckstation
         raise notice '%', vSQL; 
         raise notice '%',  concat('vRC.fid_parent: ', vRC.fid_parent::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL into vid_st_dokument using vRC.fid_parent::text, vid_projekt::uuid;
--
vSQL := 'delete                from '||vZIELSCHEMA||'.st_dokument2objekt where ( id_objekt, id_st_vw_projekt ) in ( select id, id_st_vw_projekt from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2 )'; --verundentsorgung.wa_pkt_druckstation
         raise notice '%', vSQL;
         raise notice '%', concat('vRC.fid_parent: ', vRC.fid_parent::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL using vRC.fid_parent::text, vid_projekt::uuid;
--
vSQL := 'delete                from '||vZIELSCHEMA||'.st_dokument        where id = $1 and id_st_vw_projekt = $2';
         raise notice '%', vSQL; 
         raise notice '%', concat('vid_st_dokument: ', vid_st_dokument::text,', vid_projekt: ', vid_projekt::text); 
         execute vSQL using vid_st_dokument, vid_projekt::uuid;
end if; --if 1 = 2 then 
--end if; --if vZ > 0 then
--
vid_st_dokument := gen_random_uuid();
--id des Objektes ermitteln.
vid_object := null;
vSQL := 'select id from '||vRC.zieltabelle||' where fid_hist::text = $1 and id_st_vw_projekt = $2';
execute vSQL into vid_object using vRC.fid_parent::text, vid_projekt::uuid;


if vid_object is not null then --nur wenn es das Objekt gibt, sonst macht es keinen Sinn
--
raise notice '%', '--';
raise notice '%', concat('insert into '||vZIELSCHEMA||'.st_dokument mit vid_st_dokument = ''', vid_st_dokument::text, ''', vid_object = ''', vid_object::text, '''');
raise notice '%', '--';
--
vSQL := 'insert into '||vZIELSCHEMA||'.st_dokument (
             id
           --, gueltig_von
           --, gueltig_bis
           , angelegt_am
           , angelegt_von
           , geaendert_am
           , geaendert_von
           , bemerkung
           , id_objekt
           , ident_hist
           , ident_object_hist
           , titel
           , kommentar
           , datei
           , id_st_vw_dokumenttyp
           , id_st_vw_projekt
           , id_st_vw_objektbezeichnung ) --values 
          select
             $1 --id
           --, gueltig_von
           --, gueltig_bis
           , $2 --angelegt_am
           , case when $3 is null then ''unbekannt'' else $3 end --angelegt_von
           , $4 --geaendert_am
           , case when $5 is null then ''unbekannt'' else $5 end --geaendert_von
           , $6 --bemerkung
           , $7 --id_objekt
           , $8 --ident_hist
           , $9 --ident_object_hist
           , case when $10 is null then ''unbekannt'' else $10 end --titel
           , case when $11 is null then ''unbekannt'' else $11 end --kommentar
           , case when $12 is null then ''unbekannt'' else $12 end --datei
           , $13 --id_st_vw_dokumenttyp
           , $14 --id_st_vw_projekt
           , $15 --id_st_vw_objektbezeichnung
          where not exists (select ''X'' from '||vZIELSCHEMA||'.st_dokument where id_objekt = $7 and datei = $12 and id_st_vw_projekt = $14 )
          RETURNING id        
';
--raise notice '%', concat('vid_object: ', vid_object::text);
execute vSQL into vid_st_dokument_returning using vid_st_dokument::uuid, vRC.sg_insrtdat, vRC.sg_insrtuser, vRC.sg_updtdat,  vRC.sg_updtuser, vRC.commentary 
                 , vid_object::uuid, vRC.fid_parent::text, vRC.fid_parent::text, vRC.title, vRC.commentary, vRC.filename::text
                 , '00000000-0000-0000-0000-000000000000'::uuid, vid_projekt::uuid, '00000000-0000-0000-0000-000000000000'::uuid   ;
raise notice '%', concat('vid_st_dokument_returning = ''', vid_st_dokument_returning::text, '''');
vSQL := 'select count(*) from '||vZIELSCHEMA||'.st_dokument where id = $1';
         execute vSQL into vZ3 using vid_st_dokument::uuid; 
         raise notice '%', concat('vZ3 = ''', vZ3::text, '''');
vSQL := 'insert into '||vZIELSCHEMA||'.st_dokument2objekt (
             angelegt_am
           , angelegt_von
           , geaendert_am
           , geaendert_von
           , bemerkung
           , id_st_dokument
           , id_objekt
           , id_st_vw_projekt 
           )
          select 
             $1 --angelegt_am
           , case when $2 is null then ''unbekannt'' else $2 end --angelegt_von
           , $3 --geaendert_am
           , case when $4 is null then ''unbekannt'' else $4 end --geaendert_von
           , $5 --bemerkung
           , $6 --id_st_dokument
           , $7 --id_objekt
           , $8 --id_st_vw_projekt 
          where not exists 
            (select ''X'' from '||vZIELSCHEMA||'.st_dokument2objekt 
               where id_objekt = $7 
                 and id_st_dokument= $6 
                 and id_st_vw_projekt = $8 )
                and exists 
             (select ''X'' from '||vZIELSCHEMA||'.st_dokument 
                where id_st_vw_projekt = $8 
                  and id               = $6 )';
raise notice '%', '--';
raise notice '%', concat('insert into '||vZIELSCHEMA||'.st_dokument2objekt mit vid_st_dokument = ''', vid_st_dokument::text
                          , ''', vid_object = ''', vid_object::text, '''');
raise notice '%', '--';

execute vSQL using vRC.sg_insrtdat, vRC.sg_insrtuser::text, vRC.sg_updtdat,  vRC.sg_updtuser::text
                 , concat(vRC.quelltabelle, ', ', vRC.zieltabelle, ', ', vRC.fid_parent::text)::text
                 , vid_st_dokument::uuid
                 , vid_object::uuid
                 , vid_projekt::uuid;
--
end if; --if vid_object is not null then

end loop;

