--
-- TOC entry 24815 (class 1255 OID 52914869)
-- Name: migration_100_protokoll(text, text, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.migration_100_protokoll(vid_projekt text, vquell_table_name text, vziel_table_name text, vbedingung text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
vSQL text;
vRETURN text;
vQUELLSCHEMA text;
vZQUELLE integer default 0;
vZZIEL integer default 0;
	BEGIN
--select verundentsorgung.migration_100_protokoll( '00000000-0000-0000-0000-000000000001', 'v_ww_section_s_concat', 'aw_lin_haltung', ' ''1'' = ''1'' ');
if vid_projekt = '00000000-0000-0000-0000-000000000001' then vQUELLSCHEMA = 'bereitschaftsauskunft'; elseif vid_projekt = '00000000-0000-0000-0000-000000000003' then vQUELLSCHEMA = 'bereitschaftsauskunft_zkwal'; end if; 
vSQL := 'select count(*) from '||vQUELLSCHEMA||'.'||vquell_table_name||' where '||vbedingung||';'; raise notice '%', vSQL; 
execute vSQL into vZQUELLE;
vSQL := 'select count(*) from verundentsorgung.'||vziel_table_name||'    where id_st_vw_projekt::text = '''||vid_projekt||''';'; raise notice '%', vSQL; 
execute vSQL into vZZIEL;
vRETURN := 
concat('
', vZQUELLE::text, ' DS, Quelltabelle: ', vquell_table_name, ', ', 'Bedingung: where ', vbedingung, '
', vZZIEL::text,   ' DS, Zieltabelle:  ', vziel_table_name,  '
'); raise notice '%', vRETURN;
return concat('Differenz: ', abs(vZQUELLE - vZZIEL)::text, ' DS');
	END;
$$;


