--

CREATE FUNCTION verundentsorgung.migration_test(vscript_name text, vzielprojekt text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vRETURN       text default 't';
vZ            integer default 0;
vZ1           integer default 0;
vZ2           integer default 0;
vDUMMY        text default 'Fehler!';
vSQL          text default 'Fehler!';
vRC           RECORD;
vRC_TABLES    RECORD;
vQUELLSCHEMA  text ;
vQUELLTABELLE text default 'verundentsorgung';
vZIELSCHEMA   text default 'verundentsorgung';
vZIELTABELLE  text default 'verundentsorgung';
vscript       text default 'Fehler!';
vPROJEKT_NAME text default 'ZVG';
vID_PROJEKT   text default '00000000-0000-0000-0000-000000000000';
vID_DEFAULT   text default '00000000-0000-0000-0000-000000000000';
vKURZTEXT_DEFAULT   text default 'unbekannt';
vMIGRATIONTESTORT   text default 'Grevesmühlen';
--
  verror_state      text;
  verror_text       text;
  verror_detail     text;
  verror_hint       text;
  verror_context    text;
--
begin
vSQL := 'select id::text from "'||vZIELSCHEMA||'"."st_vw_projekt" where kurztext = $1'; execute vSQL into vID_PROJEKT using vzielprojekt;
raise notice '%', vID_PROJEKT;
--
--
--
if vscript_name = 'migration_test' then
raise notice '%', vscript_name;
if vzielprojekt = 'ZVG' then vQUELLSCHEMA  := 'bereitschaftsauskunft';  elseif vzielprojekt = 'ZKWAL' then vQUELLSCHEMA  := 'bereitschaftsauskunft_zkwal'; end if;
vZIELSCHEMA   := 'verundentsorgung';
raise notice '%', vQUELLSCHEMA;


perform verundentsorgung.admin_layerstruktur2admin_symbole_mv_refresh(vZIELSCHEMA::text, vid_projekt::uuid, 0::text, 1::text);
--
--
--select verundentsorgung.select_admin_projekt_parameter( 'history', '00000000-0000-0000-0000-000000000001', 'wert_aktivstatus' );
vSQL := 'update "'||vZIELSCHEMA||'"."admin_projekt_parameter" set "wert_aktivstatus" = $1 where kurztext = $2'; raise notice '%', vSQL; execute vSQL using 0, 'historie';
--
--update verundentsorgung.admin_projekt_parameter set wert_aktivstatus = '0' where kurztext = 'name_number' and id_st_vw_projekt = '00000000-0000-0000-0000-000000000001';
--raise notice '%', 'name_number trigger wird ausgeschaltet';
vSQL := 'update "'||vZIELSCHEMA||'"."admin_projekt_parameter" set "wert_aktivstatus" = ''0'' where kurztext = ''name_number'' and id_st_vw_projekt::uuid = $1::uuid'; raise notice '%', vSQL; execute vSQL using vid_projekt, vquellschema  ;
--
--vSQL := 'Beginn "'||vZIELSCHEMA||'"."migration_001_delete_all_schema_tables"'; raise notice '%', vSQL;
--vSQL := 'select "'||vZIELSCHEMA||'"."migration_001_delete_all_schema_tables"(''migration_001_delete_all_schema_tables'', $1, $2)'; raise notice '%', vSQL; execute vSQL using vid_projekt, vquellschema  into vDUMMY;
--vSQL := 'Ende   "'||vZIELSCHEMA||'"."migration_001_delete_all_schema_tables"'; raise notice '%', vSQL;
