--

CREATE FUNCTION verundentsorgung.migration_wa_label(vscript_name text, vid_projekt text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vRETURN       text default 't';
vZ            integer default 0;
vZ1           integer default 0;
vZ2           integer default 0;
vDUMMY        text default 'Fehler!';
vSQL          text default 'Fehler!';
vRC           RECORD;
vRC_TABLES    RECORD;
--vQUELLSCHEMA  text default 'verundentsorgung_oracle';
vQUELLTABELLE text default 'verundentsorgung';
vZIELSCHEMA   text default 'verundentsorgung';
vZIELTABELLE  text default 'verundentsorgung';
vscript       text default 'Fehler!';
--vPROJEKT_NAME text default 'ZVG';
--vID_PROJEKT   text default '00000000-0000-0000-0000-000000000001';
vID_DEFAULT   text default '00000000-0000-0000-0000-000000000000';
vKURZTEXT_DEFAULT   text default 'unbekannt';
vMIGRATIONTESTORT   text default 'Grevesmühlen';
begin
--vSQL := 'select id from "'||vZIELSCHEMA||'"."st_vw_projekt" where kurztext = $1'; execute vSQL into vID_PROJEKT using vPROJEKT_NAME;
if vscript_name = 'migration_wa_label' then
vZIELSCHEMA := 'verundentsorgung';
raise notice '%', vscript_name;
raise notice '%', vid_projekt;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_lin_bauwerkskante b  	 	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_lin_schutzrohr b  	 	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_lin_wasserleitung b    	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_armatur b  		 	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
