update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_brunnen b   			where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_druckminderer b    	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_druckstation b     	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_entlueftung b      	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_hausanschlusspunkt b  where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_hydrant b   			where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_label b   			where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_label b   			where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_pumpwerk b   		 	where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
