update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_topologie_default b   where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
update verundentsorgung.wa_pkt_label a set layout = b.layout from verundentsorgung.wa_pkt_verbindungen b   		where a.id_objekt = b.id and b.id_st_vw_projekt = vid_projekt::uuid;
