--
-- TOC entry 24662 (class 1255 OID 43463363)
-- Name: rgb_to_hex(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.rgb_to_hex(vrgbstring text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vR integer;
vG integer;
vB integer;
vSQL text;
BEGIN
--select verundentsorgung.rgb_to_hex( '(82,142,214,255)'::text );
--select verundentsorgung.rgb_to_hex( '(8a2,142,214,255)'::text ); --bei Fehler Schwarz '#F0F8FF'
vSQL := 'select r[1] r, r[2] g, r[3] b from ( select string_to_array( replace( replace(r, ''('', ''''), '')'',''''), '','' ) r from ( select $1 r ) r ) r';
execute vSQL into vR, vG, vB using vRGBSTRING;
    RETURN concat('#' , LPAD(TO_HEX(vr::integer), 2, '0') , LPAD(TO_HEX(vg::integer), 2, '0') , LPAD(TO_HEX(vb::integer), 2, '0'));
exception when others then return '#F0F8FF';
end;
$_$;


--
-- TOC entry 24893 (class 1255 OID 59068226)
-- Name: rgb_to_hex_2(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.rgb_to_hex_2(vrgbstring text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT
        CASE
            WHEN vrgbstring IS NULL THEN '#F0F8FF'
            ELSE
                '#' ||
                lpad(to_hex((parts[1])::int), 2, '0') ||
                lpad(to_hex((parts[2])::int), 2, '0') ||
                lpad(to_hex((parts[3])::int), 2, '0')
        END
    FROM (
        SELECT string_to_array(
                   replace(replace(vrgbstring, '(', ''), ')', ''),
                   ','
               ) AS parts
    ) s;
$$;


--
-- TOC entry 24639 (class 1255 OID 39683685)
-- Name: select_admin_projekt_parameter(text, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.select_admin_projekt_parameter(vkurztext text, vid_st_vw_projekt text, vreturnvalue text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vZ       integer default 0;
vSQL     text;
vRETURN  text default '0';
vNOTICE  text default '0';
vEXECUTE text default '1';
vSCHEMA_name text default 'verundentsorgung';
--
  verror_state      text;
  verror_text       text;
  verror_detail     text;
  verror_hint       text;
  verror_context    text;
--
begin
--select verundentsorgung.select_admin_projekt_parameter( 'historie', '00000000-0000-0000-0000-000000000001', 'wert_aktivstatus' );
--select verundentsorgung.select_admin_projekt_parameter( 'name_number', '00000000-0000-0000-0000-000000000001', 'wert_aktivstatus' );
if vRETURNVALUE = 'wert_aktivstatus' then
vSQL := 'select count(*) from '||vSCHEMA_name||'.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2';
if vNOTICE  = '1' then raise notice '%', vSQL; end if;
if vEXECUTE = '1' then execute vSQL into vZ using vKURZTEXT, vid_st_vw_projekt; end if;
vRETURN := vZ::text;
end if; --if vRETURNVALUE = 'wert_aktivstatus' then
return vRETURN;
--RAISE EXCEPTION 'Ein Fehler ist aufgetreten';
EXCEPTION
  WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS 
    verror_state  = RETURNED_SQLSTATE,
    verror_text   = MESSAGE_TEXT,
    verror_detail = PG_EXCEPTION_DETAIL,
    verror_hint   = PG_EXCEPTION_HINT,
    verror_context= PG_EXCEPTION_CONTEXT;
    PERFORM verundentsorgung.f_admin_error_log( verror_state, verror_text, verror_detail, verror_hint, verror_context, 'select_admin_projekt_parameter', vid_st_vw_projekt );
RAISE;
end; $_$;


