--

CREATE FUNCTION verundentsorgung.tf_all_tables_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
vTG_TABLE_SCHEMA      text default TG_TABLE_SCHEMA ;
vTG_TABLE_NAME        text default TG_TABLE_NAME ;
vTG_OP                text default TG_OP ;
vUUID                 text;
vaktivstatus          text default '1';
vwert_numerisch       text default '0';
vSQL                  text;
vZ                    integer;
--
vpid                  text;
vdatname              text;
vapplication_name     text;
vclient_addr          text;
vclient_hostname      text;
vclient_port          text;
vbackend_type         text;
BEGIN
if 1 = 2 then --wird ab sofor über Trigger verundentsorgung.tf_standard_after umgesetzt
vSQL := 'select aktivstatus::text, wert_numerisch::text from admin.sec_projekt_parameter where kurztext = $1';
execute vSQL into vaktivstatus, vwert_numerisch using 'historystatus';
-- select pid, datname, usename, application_name, client_addr, client_hostname, client_port, backend_type 
--   from pg_stat_activity where pid = pg_backend_pid();
	if vaktivstatus = '0' then
	  vsql := 'create table if not exists '||TG_TABLE_SCHEMA||'_hist.'||TG_TABLE_NAME||' as
               select '' ''::text hist_uuid, '' ''::text hist_operation, now()::timestamp hist_stamp, '' ''::text hist_userid
               , '' ''::text hist_pid, '' ''::text hist_datname, '' ''::text hist_application_name, '' ''::text hist_client_addr, '' ''::text hist_client_hostname, '' ''::text hist_client_port, '' ''::text hist_backend_type
               , T.* from '||TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||' T where 1 = 2';
	  execute vSQL;
	end if;
--
        IF ( TG_OP in ('DELETE','UPDATE') and vaktivstatus = '0' ) then
           vUUID := uuid_generate_v4();
           vsql  := 'select   pid,  datname,  application_name,  client_addr,  client_hostname,  client_port,  backend_type from pg_stat_activity where pid = $1';
           execute vSQL into vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type using pg_backend_pid();
--           vsql  := 'INSERT INTO '||vTG_TABLE_SCHEMA||'_hist.'||vTG_TABLE_NAME||'
--                     SELECT '''||vUUID||''', '''||vTG_OP||''', now(), user
--                     , o.* FROM old_table o'; --execute vsql;
           vsql  := 'INSERT INTO '||vTG_TABLE_SCHEMA||'_hist.'||vTG_TABLE_NAME||'
                     SELECT $1, $2, now(), user, $3, $4, $5, $6, $7, $8, $9, o.* FROM old_table o'; 
           execute vsql using vUUID, vTG_OP, vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type;
      /*ELSIF ( TG_OP = 'UPDATE' and vaktivstatus = '0' ) THEN
           vsql := 'INSERT INTO '||vTG_TABLE_SCHEMA||'.'||vTG_TABLE_NAME||'
                SELECT ''U'', now(), user, n.* FROM new_table n'; execute vsql;
        ELSIF ( TG_OP = 'INSERT' and vaktivstatus = '0' ) THEN
           vsql := 'INSERT INTO '||vTG_TABLE_SCHEMA||'.'||vTG_TABLE_NAME||'
                SELECT ''U'', now(), user, n.* FROM new_table n'; execute vsql;*/
        END IF;
        end if; --if 1 = 2 then --wird ab sofor über Trigger verundentsorgung.tf_standard_after umgesetzt
        RETURN NULL; -- result is ignored since this is an AFTER trigger
EXCEPTION WHEN OTHERS then
raise 'Trigger verundentsorgung.tf_all_tables_history() löst bei % Fehler in Tabelle % aus!', vTG_OP, vTG_TABLE_SCHEMA||'.'||vTG_TABLE_NAME ;
end;
$_$;


