--
begin
if vNOTICE = '1' then raise notice '%', concat('01. ','Beginn'); end if;

--if vFunktionszeit = 1 then	SELECT clock_timestamp() INTO vFunktionstart; end if;

vSQLAKTIVSTATUSABFRAGE := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung, sortierreihenfolge, bemerkung from verundentsorgung.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2';

/*
