CREATE FUNCTION verundentsorgung.tf_standard_before() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
--diese Variablen werden aus der Tabelle verundentsorgung.admin_projekt_parameter entsprechend des Anwendungsfalls ausgelesen
vPROJEKTPARAMETER_WERT_KURZTEXT           text;
vPROJEKTPARAMETER_WERT_AKTIVSTATUS        numeric;
