vwait_event_type      text;
vwait_event           text;
vstate                text;
vbackend_xid          text; 
vbackend_xmin         text;
vquery                text;
vbackend_type         text;
--
verror_state          text;
verror_text           text;
verror_detail         text;
verror_hint           text;
verror_context        text;  
--
vid_st_vw_projekt     uuid;    --Dies ist Bestandteil jeder Transaktion und weiter unten so abgefragt: if TG_OP in ('INSERT', 'UPDATE') then vid_st_vw_projekt := new.d_st_vw_projekt; else vid_st_vw_projekt := old.d_st_vw_projekt; end if;
--
vUUID                 uuid;    --Bei INSERT: Wird weiter unten bei Bedarf ermittelt und für andere Aktionen, wie Schreiben von Historie durchgängig verwendet
vSQL                  text;    --wird in verschiedenen Fällen für dynamisches SQL verwendet und an execute übergeben
vZ                    integer; --wird in verschiedenen Fällen als Zähler verwendet
vRC                   record;  --Dient zur Random Ermittlung der name_number
vCHARS                char[];  --Dient zur Random Ermittlung der name_number
vNAME_NUMBER          text;    --Dient zur Random Ermittlung der name_number
vNEW_NAME_NUMBER      text;    --Dient zur Random Ermittlung der name_number
vNAME_NUMBER_PRAEFIX  text;    --Dient zur Random Ermittlung der name_number  
vLAENGE               numeric;
vGEFAELLE             numeric;
vFLAECHE              numeric;
vTABLE_NAME           text;    --Dient zum Anlegen der entsprechenden Topologie Begrenzungs Objektklasse
--vid_st_vw_projekt        uuid;  --15 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_betriebsstatus uuid;  --16 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_eigentuemer    uuid;  --17 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_betreiber      uuid;  --18 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_material       uuid;  --19 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_medium         uuid;  --20 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_lagestatus     uuid;  --21 Dient zum Anlegen der Topologie Objektklasse
vid_st_vw_topologie      uuid;  --22 Dient zum Anlegen der Topologie Objektklasse
vid_knoten_oben          uuid;
vid_knoten_unten         uuid;
vid_st_strasse           uuid;
vID                      uuid;
vid_aw_lin_haltung_connector uuid;
vid_wa_lin_wasserleitung_connector uuid;
vtyp_id                  text;
vmedium                  uuid;
veinlaufnummer           text;
--
vknoten_oben             text;
vknoten_unten            text;
vKNOTEN_NAME_NUMBER      text;
vhaltung_connector       text;
vSQL_layout              text;
vschutzpunkt_id uuid;
--
vNOTICE_PRAEFIX       text default concat('TG_NAME: ', TG_NAME, ', TG_TABLE_SCHEMA: ', TG_TABLE_SCHEMA, ', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_OP: ', TG_OP);
--vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type
vNOTIZEN              integer default 0; --Wenn zum Tracen kurzzeitig individuell mehr Marken ausgegeben werden sollen, muss hier 1, sonst 0 stehen.
vNOTIZENTEXT          text; 
vEXECUTE              integer default 1;
vSQLAKTIVSTATUSABFRAGE text; 
vLayoutparameter       text;
vtest1234 text;
vSPLIT_SEGMENT         geometry;
vtest12345 text;
