--
vid_st_vw_objektbezeichnung uuid; --add ew 04.08.2025
vid_st_vw_dokumenttyp       uuid; --add ew 04.08.2025
--
vDUMMY                 text default 'Fehler!';
--
vStartzeit  TIMESTAMP;
vEndzeit    TIMESTAMP;
vLaufzeit integer default 1;
--
vFunktionstart  TIMESTAMP;
vFunktionende    TIMESTAMP;
vFunktionszeit integer default 0;

--
begin
--if vFunktionszeit = 1 then	SELECT clock_timestamp() INTO vFunktionstart; end if;
if 1=1 then 
vSQLAKTIVSTATUSABFRAGE := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung, sortierreihenfolge, bemerkung from verundentsorgung.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2';
-----------------------------------------------------------------------
  if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||'000  '||' Beginn '||'                       '||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if;
-----------------------------------------------------------------------
  if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||'000 a'||' Beginn '||'setze vid_st_vw_projekt'||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if;
  if     TG_OP in ('INSERT')           then vid_st_vw_projekt := new.id_st_vw_projekt;
  elseif TG_OP in ('UPDATE', 'DELETE') then vid_st_vw_projekt := old.id_st_vw_projekt;
  end if;
  if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||'000 a'||' ENDE   '||'setze vid_st_vw_projekt'||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ', vid_st_vw_projekt: ', vid_st_vw_projekt ); end if;
-----------------------------------------------------------------------
vPROJEKTPARAMETER_WERT_KURZTEXT := 'historie';
 execute vSQLAKTIVSTATUSABFRAGE into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_text, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung, vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE, vPROJEKTPARAMETER_WERT_BEMERKUNG using vPROJEKTPARAMETER_WERT_KURZTEXT, vid_st_vw_projekt;
	if ( TG_OP in ('DELETE','UPDATE') and vPROJEKTPARAMETER_WERT_AKTIVSTATUS = '1' ) then
      --Anfang ggf. Tabelle anlegen
	  vsql := 'create table if not exists '||TG_TABLE_SCHEMA||'_hist.'||TG_TABLE_NAME||' as
               select 
                 uuid_generate_v4()::uuid     hist_uuid
               , now()::timestamptz           hist_timestamptz
               , '' ''::text                  hist_tg_op
               , '' ''::text                  hist_datid
               , '' ''::text                  hist_datname -- ::text
               , '' ''::text                  hist_pid -- ::text
               , '' ''::text                  hist_leader_pid -- ::text
               , '' ''::text                  hist_usesysid -- ::text
               , '' ''::text                  hist_sename -- ::text
               , '' ''::text                  hist_application_name -- ::text
               , '' ''::text                  hist_client_addr -- ::text
               , '' ''::text                  hist_client_hostname -- ::text
               , '' ''::text                  hist_client_port -- ::text
               , '' ''::text                  hist_backend_start -- ::text
               , '' ''::text                  hist_xact_start -- ::text
               , '' ''::text                  hist_query_start -- ::text
               , '' ''::text                  hist_state_change -- ::text
               , '' ''::text                  hist_wait_event_type -- ::text
               , '' ''::text                  hist_wait_event -- ::text
               , '' ''::text                  hist_state -- ::text
               , '' ''::text                  hist_backend_xid -- ::text
               , '' ''::text                  hist_backend_xmin -- ::text
               , '' ''::text                  hist_query -- ::text
               , '' ''::text                  hist_backend_type -- ::text
               , T.* from '||TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||' T where 1 = 2';
	  execute vSQL;
      --Ende ggf. Tabelle anlegen
      --Anfang Systemvariablen füllen
     vSQL := 'select 
                datid::text
              , datname::text
              , pid::text
              , leader_pid::text
              , usesysid::text
              , usename::text
              , application_name::text
              , client_addr::text
              , client_hostname::text
              , client_port::text
              , backend_start::text
              , xact_start::text
              , query_start::text
              , state_change::text
              , wait_event_type::text
              , wait_event::text
              , state::text
              , backend_xid::text
              , backend_xmin::text
              , query::text
              , backend_type::text
           FROM pg_stat_activity where pid = $1 ';
     execute vSQL into 
                vdatid                --text;
              , vdatname              --text; 
              , vpid                  --text;
              , vleader_pid           --text;
              , vusesysid             --text;
              , vusename              --text;
              , vapplication_name     --text;
              , vclient_addr          --text;
              , vclient_hostname      --text;
              , vclient_port          --text;
              , vbackend_start        --text;
              , vxact_start           --text;
              , vquery_start          --text;
              , vstate_change         --text;
              , vwait_event_type      --text;
              , vwait_event           --text;
              , vstate                --text;
              , vbackend_xid          --text; 
              , vbackend_xmin         --text;
              , vquery                --text;
              , vbackend_type         --text;
             using pg_backend_pid();
           vsql  := 'INSERT INTO '||TG_TABLE_SCHEMA||'_hist.'||TG_TABLE_NAME||'
                     SELECT 
                 $1,  --uid_generate_v4()::uuid        hist_uuid
                 $2,  --, now()::timestamptz           hist_timestamptz
                 $3,  --, '' ''::text                  hist_tg_op
                 $4,  --, '' ''::text                  hist_datid
                 $5,  --, '' ''::text                  hist_datname -- ::text
                 $6,  --, '' ''::text                  hist_pid -- ::text
                 $7,  --, '' ''::text                  hist_leader_pid -- ::text
                 $8,  --, '' ''::text                  hist_usesysid -- ::text
                 $9,  --, '' ''::text                  hist_sename -- ::text
                 $10, --, '' ''::text                  hist_application_name -- ::text
                 $11, --, '' ''::text                  hist_client_addr -- ::text
                 $12, --, '' ''::text                  hist_client_hostname -- ::text
                 $13, --, '' ''::text                  hist_client_port -- ::text
                 $14, --, '' ''::text                  hist_backend_start -- ::text
                 $15, --, '' ''::text                  hist_xact_start -- ::text
                 $16, --, '' ''::text                  hist_query_start -- ::text
                 $17, --, '' ''::text                  hist_state_change -- ::text
                 $18, --, '' ''::text                  hist_wait_event_type -- ::text
