                      -- Knoten oben in Haltung eintragen
                     vSQL := 'select t.id::uuid, t.name_number ||'', ''||(t.layout->>''table_name'')||'', ''||(t.layout->>''pkt_symbolname'') as  name_number from  '||TG_TABLE_SCHEMA||'.wa_pkt_topologie_v_mv t
