--
vid_st_vw_projekt     uuid;    --Dies ist Bestandteil jeder Transaktion und weiter unten so abgefragt: if TG_OP in ('INSERT', 'UPDATE') then vid_st_vw_projekt := new.d_st_vw_projekt; else vid_st_vw_projekt := old.d_st_vw_projekt; end if;
