vid_knoten_oben          uuid;
vid_knoten_unten         uuid;
vid_st_strasse           uuid;
vID                      uuid;
vid_aw_lin_haltung_connector uuid;
vtyp_id                  text;
vmedium                  uuid;
veinlaufnummer           text;
--
vknoten_oben             text;
vknoten_unten            text;
vKNOTEN_NAME_NUMBER      text;
vhaltung_connector       text;
vSQL_layout              text;
--
vNOTICE_PRAEFIX       text default concat('TG_NAME: ', TG_NAME, ', TG_TABLE_SCHEMA: ', TG_TABLE_SCHEMA, ', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_OP: ', TG_OP);
--vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type
vNOTIZEN              integer default 0; --Wenn zum Tracen kurzzeitig individuell mehr Marken ausgegeben werden sollen, muss hier 1, sonst 0 stehen.
