begin
if vFunktionszeit = 1 then	SELECT clock_timestamp() INTO vFunktionstart; end if;
if 1=1 then 
vSQLAKTIVSTATUSABFRAGE := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung, sortierreihenfolge, bemerkung from '||TG_TABLE_SCHEMA||'.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2';
