  if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||'000  '||' Beginn '||'                       '||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if;
-----------------------------------------------------------------------
  if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||'000 a'||' Beginn '||'setze vid_st_vw_projekt'||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if;
  if     TG_OP in ('INSERT')           then vid_st_vw_projekt := new.id_st_vw_projekt;
