        if     vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 and new.id is null then 
           if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' a Beginn '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if; 
           vUUID := uuid_generate_v4()::uuid; 
          new.id := vUUID::uuid; 
        elseif vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 and new.id is not null and new.id::text like '________-____-____-____-____________' then 
           if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' b Beginn '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME ); end if; 
           vUUID := new.id::uuid; 
          new.id := vUUID::uuid; 
        end if; --if     vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 and new.id is null then
           if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||'   ENDE   '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text ); end if;
  elseif TG_OP = 'UPDATE' then 
           vUUID := old.id::uuid;  
  end if;  --if TG_OP = 'INSERT' then
IF vLaufzeit = 1 THEN  SELECT clock_timestamp() INTO vEndzeit;
        RAISE NOTICE 'id erstellen: % Sekunden',  EXTRACT(EPOCH FROM (vEndzeit - vStartzeit));
END IF;
-----------------------------------------------------------------------
