vSQL := 'select hl.id id_aw_lin_haltung_connector, concat(hl.name_number, '', '', med.kurztext) name_number --, hlm.kurztext, al.name_number, alm.kurztext 
                   from  '||TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||' hl
                       , '||TG_TABLE_SCHEMA||'.st_vw_medium med --ON b.id_st_vw_medium = med.id
