                       , ( select $1 id, $2 id_st_vw_projekt, $3 geometry ) al --hier nur mit neuer Geometrie arbeiten
                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium hlm
                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium alm
                   where 
 				   hl.id_st_vw_projekt  = $2
                   and hl.id_st_vw_projekt  = al.id_st_vw_projekt::uuid
                   and hl.id_st_vw_medium   = med.id
                   AND ST_DWithin(ST_EndPoint(al.geometry), hl.geometry, 0.5)
			       AND NOT ST_Within(ST_EndPoint(al.geometry), ST_StartPoint(hl.geometry))
			       AND NOT ST_Within(ST_EndPoint(al.geometry), ST_EndPoint(hl.geometry))
			       AND NOT ST_Within(ST_StartPoint(al.geometry), ST_StartPoint(hl.geometry))
			       AND NOT ST_Within(ST_StartPoint(al.geometry), ST_EndPoint(hl.geometry))
                   limit 1
                 '; 


           --if vNOTIZEN = 1 then raise notice '%', vSQL; end if;
           if vEXECUTE = 1 then execute vSQL into vid_aw_lin_haltung_connector, vNOTIZENTEXT using new.id, new.id_st_vw_projekt, new.geometry; end if;
             --if vid_aw_lin_haltung_connector is not null then new.id_aw_lin_haltung_connector = vid_aw_lin_haltung_connector; end if;
             if vid_aw_lin_haltung_connector is null then 
               new.id_wa_lin_wasserleitung_connector := null;
               new.leitung_connector           := null;
               else 
               new.id_wa_lin_wasserleitung_connector := vid_aw_lin_haltung_connector;
               new.leitung_connector           := vNOTIZENTEXT;
             end if;
         --
         end if; --if round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric > 0 then
      if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' ENDE '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text, ', vid_aw_lin_haltung_connector: ', new.id_aw_lin_haltung_connector, ', vNOTIZENTEXT: ', vNOTIZENTEXT ); end if;
      end if; --if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then
  end if; --if TG_OP = 'UPDATE' then 

