  vPROJEKTPARAMETER_WERT_KURZTEXT := 'aw_pkt_topologie_default_update'; --if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint 008 a', ' ', vPROJEKTPARAMETER_WERT_KURZTEXT); end if;
