                        if vEXECUTE = 1 then execute vSQL using vUUID, vKNOTEN_NAME_NUMBER, new.id_st_vw_projekt, vRC.id; end if;
                    end loop;
                    -- Knoten unten in Haltung eintragen
                    vSQL := 'select h.id, h.name_number from  '||TG_TABLE_SCHEMA||'.aw_lin_haltung h
                               where h.id_st_vw_projekt = $1
                                 and st_intersects( st_endpoint(h.geometry), st_buffer($2, 0.5) )'; 
                    for vRC in execute vSQL using new.id_st_vw_projekt, new.geometry loop
                       --if vNOTICE = '1' then raise notice '%', vSQL; end if;   if vEXECUTE = '1' then execute vSQL into vID using new.id_st_vw_projekt, new.geometry; end if;
                      vSQL := 'update '||TG_TABLE_SCHEMA||'.aw_lin_haltung
                                 set id_knoten_unten = $1 
