                                   where id_st_vw_projekt = $3 and id = $4'; 
                        --if vNOTIZEN = 1 then raise notice '%', vSQL; end if; 
                        if vEXECUTE = 1 then execute vSQL using vUUID, vKNOTEN_NAME_NUMBER, new.id_st_vw_projekt, vRC.id; end if;
                    end loop;
                 end if;
               --
               if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' ENDE '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text ); end if;
      end if; --if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then
  end if; --if TG_OP = 'INSERT' then
