-- gefaelle wir hier ggf. berechnet
  vPROJEKTPARAMETER_WERT_KURZTEXT := 'aw_lin_haltung_connector';
  if TG_OP in ( 'INSERT', 'UPDATE' ) and TG_TABLE_NAME = 'aw_lin_haltung' then 
  	  execute vSQLAKTIVSTATUSABFRAGE into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_text, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung, vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE, vPROJEKTPARAMETER_WERT_BEMERKUNG using vPROJEKTPARAMETER_WERT_KURZTEXT, new.id_st_vw_projekt;
      if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then 
        if round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric > 0 then
         --
        if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Beginn '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text ); end if;
        vSQL := 'select hl.id id_aw_lin_haltung_connector, hl.name_number --, hlm.kurztext, al.name_number, alm.kurztext 
                   from  '||TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||' hl
                       , ( select $1 id, $2 id_st_vw_projekt, $3 geometry ) al --hier nur mit neuer Geometrie arbeiten
                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium hlm
                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium alm
                   where 
                   --al.id = $1 
                   --and hl.id_st_vw_medium = hlm.id
                   --and al.id_st_vw_medium = alm.id
                       hl.id_st_vw_projekt  = $2
                   and hl.id_st_vw_projekt  = al.id_st_vw_projekt  
                   --and hl.id_st_vw_projekt  = hlm.id_st_vw_projekt
                   --and hl.id_st_vw_projekt  = alm.id_st_vw_projekt
                   --and substring(hlm.kurztext,1,3) = substring(alm.kurztext,1,3) --muss gleiches Medium sein
                   and st_intersects( st_endpoint( al.geometry ), st_buffer(hl.geometry, 0.5) ) = ''t''
                   and st_intersects( st_endpoint( al.geometry ), st_buffer(st_startpoint(hl.geometry), 0.5) ) = ''f''
                   and st_intersects( st_endpoint( al.geometry ), st_buffer(st_endpoint(hl.geometry), 0.5) ) = ''f''
                   and st_intersects( st_startpoint( al.geometry ), st_buffer(st_startpoint(hl.geometry), 0.5) ) = ''f''
                   and st_intersects( st_startpoint( al.geometry ), st_buffer(st_endpoint(hl.geometry), 0.5) ) = ''f''
                   limit 1
                 ';
           --if vNOTIZEN = 1 then raise notice '%', vSQL; end if;
           if vEXECUTE = 1 then execute vSQL into vid_aw_lin_haltung_connector, vNOTIZENTEXT using new.id, new.id_st_vw_projekt, new.geometry; end if;
             --if vid_aw_lin_haltung_connector is not null then new.id_aw_lin_haltung_connector = vid_aw_lin_haltung_connector; end if;
             if vid_aw_lin_haltung_connector is null then 
               new.id_aw_lin_haltung_connector := null;
               new.haltung_connector           := null;
               else 
               new.id_aw_lin_haltung_connector := vid_aw_lin_haltung_connector; 
               new.haltung_connector           := vNOTIZENTEXT;
             end if;
         --
         end if; --if round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric > 0 then
      if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' ENDE '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text, ', vid_aw_lin_haltung_connector: ', new.id_aw_lin_haltung_connector, ', vNOTIZENTEXT: ', vNOTIZENTEXT ); end if;
      end if; --if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then
  end if; --if TG_OP = 'UPDATE' then 
