                                  and st_intersects( t.geometry , st_buffer( $2, 0.5) ) limit 1'; --select t.id from  verundentsorgung.aw_pkt_topologie_v t where t.id_st_vw_projekt = '00000000-0000-0000-0000-000000000001' and st_intersects( t.geometry , st_buffer( (select st_startpoint(geometry) from verundentsorgung.aw_lin_haltung where name_number = 'WW07130529' and id_st_vw_projekt = '00000000-0000-0000-0000-000000000001'), 0.5) ) limit 1
                     execute vSQL into vid_knoten_oben, vknoten_oben using new.id_st_vw_projekt, st_startpoint( new.geometry );
                       if vid_knoten_oben is null then new.id_knoten_oben := '00000000-0000-0000-0000-000000000000'::uuid; else new.id_knoten_oben := vid_knoten_oben; end if;
