                    -- Knoten unten in Haltung eintragen
                     vSQL := 'select t.id::uuid, t.name_number from  '||TG_TABLE_SCHEMA||'.aw_pkt_topologie_v t
                                where t.id_st_vw_projekt = $1
                                  and st_intersects( t.geometry , st_buffer( $2, 0.5) ) limit 1'; 
                     execute vSQL into vid_knoten_unten, vknoten_unten using new.id_st_vw_projekt, st_endpoint( new.geometry );
                       if vid_knoten_unten is null then new.id_knoten_oben := '00000000-0000-0000-0000-000000000000'::uuid; else new.id_knoten_unten := vid_knoten_unten; end if;
                       if vid_knoten_unten is null then new.knoten_unten := null; else new.knoten_unten := vknoten_unten; end if;
