         if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Ende id_knoten_unten '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text, ', id_knoten_unten: ', new.id_knoten_unten::text ); end if;  
