CREATE FUNCTION verundentsorgung.tmp_haltungswinkel_am_punkt(haltung public.geometry, punkt public.geometry) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    punkt_haltung double precision;
    winkel double precision;
    punkt_haltung_vor geometry;
    punkt_haltung_hinter geometry;
BEGIN
    
    punkt_haltung := ST_LineLocatePoint(Haltung, punkt);

    punkt_haltung_vor := ST_LineInterpolatePoint(haltung, GREATEST(punkt_haltung - 0.00001, 0));
    punkt_haltung_hinter  := ST_LineInterpolatePoint(haltung, LEAST(punkt_haltung + 0.00001, 1));

    -- Compute the azimuth (radians → degrees)
    winkel := degrees(ST_Azimuth(punkt_haltung_vor, punkt_haltung_hinter)) -90;

    RETURN winkel;
END;
$$;


