--
-- TOC entry 14215 (class 1259 OID 43600116)
-- Name: strassenschluessel_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.strassenschluessel_v AS
 SELECT a.id_st_strasse,
    a.strasse,
    a.zuordnung,
    a.gueltig_von_strasse,
    a.gueltig_bis_strasse,
    a.id_st_amt,
    a.amt,
    a.gueltig_von_amt,
    a.gueltig_bis_amt,
    a.id_st_gemeinde,
    a.gemeinde,
    a.alkis_gemshl,
    a.gueltig_von_gemeinde,
    a.gueltig_bis_gemeinde,
    a.id_st_ort,
    a.ort,
    a.gueltig_von_ort,
    a.gueltig_bis_ort,
    a.id,
    a.zuordnung AS id_suche,
    a.id_st_vw_projekt,
    a.projekt_kurztext,
    a.projekt_langtext
   FROM ( SELECT s.id,
            s.id AS id_st_strasse,
            s.strasse,
            ((((s.strasse || ', Ort: '::text) || o.ort) || ', Gemeinde: '::text) || g.gemeinde) AS zuordnung,
            (s.gueltig_von)::text AS gueltig_von_strasse,
            (s.gueltig_bis)::text AS gueltig_bis_strasse,
            a_1.id AS id_st_amt,
            a_1.amt,
            (a_1.gueltig_von)::text AS gueltig_von_amt,
            (a_1.gueltig_bis)::text AS gueltig_bis_amt,
            g.id AS id_st_gemeinde,
            g.gemeinde,
            g.alkis_gemshl,
            (g.gueltig_von)::text AS gueltig_von_gemeinde,
            (g.gueltig_bis)::text AS gueltig_bis_gemeinde,
            o.id AS id_st_ort,
            o.ort,
            (o.gueltig_von)::text AS gueltig_von_ort,
            (o.gueltig_bis)::text AS gueltig_bis_ort,
            p.id AS id_st_vw_projekt,
            p.kurztext AS projekt_kurztext,
            p.langtext AS projekt_langtext
           FROM verundentsorgung.st_amt a_1,
            verundentsorgung.st_gemeinde g,
            verundentsorgung.st_ort o,
            verundentsorgung.st_strasse s,
            verundentsorgung.st_vw_projekt p
          WHERE ((a_1.id_st_vw_projekt = p.id) AND (g.id_st_vw_projekt = p.id) AND (o.id_st_vw_projekt = p.id) AND (s.id_st_vw_projekt = p.id) AND (a_1.id = g.id_st_amt) AND (g.id = o.id_st_gemeinde) AND (o.id = s.id_st_ort) AND (a_1.gueltig_bis > now()) AND (g.gueltig_bis > now()) AND (o.gueltig_bis > now()) AND (s.gueltig_bis > now()) AND (p.gueltig_bis > now()) AND ((1 = 1) OR (s.strasse <> '-'::text)) AND ((1 = 1) OR (a_1.amt = ANY (ARRAY['Amt Schönberger Land'::text, 'Amt Klützer Winkel'::text, 'Stadt Grevesmühlen'::text, 'Amt Grevesmühlen Land'::text]))))) a;


