-- TOC entry 21011 (class 1259 OID 46620161)
-- Name: wa_pkt_beprobungspunkt_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.wa_pkt_beprobungspunkt_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
