-- Name: aw_lin_haltung_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_lin_haltung_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
    b.bemerkung,
    b.id_st_strasse,
    b.hausnummer,
    b.hausnummerzusatz,
    b.lagezusatz,
    b.herkunftsplan,
    b.id_st_vw_projekt,
    b.id_st_vw_betriebsstatus,
    b.id_st_vw_eigentuemer,
    b.id_st_vw_betreiber,
    b.id_st_vw_material,
    b.id_st_vw_medium,
    b.id_st_vw_lagestatus,
    b.geometry,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    bs.kurztext AS betriebsstatus_kurztext,
    bs.langtext AS betriebsstatus_langtext,
    eig.kurztext AS eigentuemer_kurztext,
    eig.langtext AS eigentuemer_langtext,
    betr.kurztext AS betreiber_kurztext,
    betr.langtext AS betreiber_langtext,
    mat.kurztext AS material_kurztext,
    mat.langtext AS material_langtext,
    med.kurztext AS medium_kurztext,
    med.langtext AS medium_langtext,
    ls.kurztext AS lagestatus_kurztext,
    ls.langtext AS lagestatus_langtext,
    sch.deckelhoehe AS gelaendehoehe_knoten_oben,
    scha.deckelhoehe AS gelaendehoehe_knoten_unten,
    (b.baujahr)::text AS baujahr,
    b.id_knoten_oben,
    b.id_knoten_unten,
    (b.nennweite)::text AS nennweite,
    (b.aussendurchmesser)::text AS aussendurchmesser,
    (b.sohle_einlaufschacht)::text AS sohle_einlaufschacht,
    (b.fallhoehe_einlaufschacht)::text AS fallhoehe_einlaufschacht,
    b.einlaufnummer,
    replace((round(b.ablaufhoehe, 2))::text, '.'::text, ','::text) AS ablaufhoehe,
    sve.kurztext AS auslaufnummer,
    replace((round(b.einlaufhoehe, 2))::text, '.'::text, ','::text) AS einlaufhoehe,
    replace((round((public.st_length(b.geometry))::numeric, 2))::text, '.'::text, ','::text) AS laenge,
    replace((round(b.sohle_ablaufschacht, 2))::text, '.'::text, ','::text) AS sohle_ablaufschacht,
    (b.haltungsgefaelle)::text AS haltungsgefaelle,
    (b.wandstaerke)::text AS wandstaerke,
    b.plannummer,
    b.knoten_oben,
    b.knoten_unten,
    ((b.name_number || ''::text) || s.ort) AS test,
    vt.kurztext AS verlegetyp_kurztext,
    vt.langtext AS verlegetyp_langtext,
    b.layout,
    concat(b.name_number, ' ', 'AW-Halt.-Leitung') AS id_suche,
    concat('WW_SECTION_', b.name_number) AS kanio_id,
    'keine Angaben'::text AS twsz,
        CASE
            WHEN ((med.kurztext ~~ 'KR%'::text) OR (med.kurztext ~~ 'KDL%'::text) OR (med.kurztext = ANY (ARRAY['GW'::text, 'RDL_GAL'::text]))) THEN 'Regenwasser'::text
            WHEN ((med.kurztext ~~ 'KS%'::text) OR (med.kurztext ~~ 'ADL%'::text) OR (med.kurztext ~~ 'VS%'::text) OR (med.kurztext ~~ 'u'::text)) THEN 'Schmutzwasser'::text
            WHEN (med.kurztext ~~ 'KM%'::text) THEN 'Mischwasser'::text
            ELSE NULL::text
        END AS kanio_entw,
    b.id_st_vw_verlegetyp
   FROM ((((((((((((verundentsorgung.aw_lin_haltung b
     LEFT JOIN verundentsorgung.strassenschluessel_v s ON ((b.id_st_strasse = s.id)))
     LEFT JOIN verundentsorgung.st_vw_projekt p ON ((b.id_st_vw_projekt = p.id)))
     LEFT JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((b.id_st_vw_betriebsstatus = bs.id)))
     LEFT JOIN verundentsorgung.st_vw_eigentuemer eig ON ((b.id_st_vw_eigentuemer = eig.id)))
     LEFT JOIN verundentsorgung.st_vw_betreiber betr ON ((b.id_st_vw_betreiber = betr.id)))
     LEFT JOIN verundentsorgung.st_vw_material mat ON ((b.id_st_vw_material = mat.id)))
     LEFT JOIN verundentsorgung.st_vw_medium med ON ((b.id_st_vw_medium = med.id)))
     LEFT JOIN verundentsorgung.st_vw_lagestatus ls ON ((b.id_st_vw_lagestatus = ls.id)))
     LEFT JOIN verundentsorgung.aw_pkt_schacht sch ON ((b.knoten_oben = sch.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_schacht scha ON ((b.knoten_unten = scha.name_number)))
     LEFT JOIN verundentsorgung.st_vw_verlegetyp vt ON ((b.id_st_vw_verlegetyp = vt.id)))
     LEFT JOIN verundentsorgung.st_vw_einlaufnummer sve ON ((b.id_st_vw_einlaufnummer = sve.id)))
  WHERE (b.gueltig_bis > now());


