--
-- TOC entry 21290 (class 1259 OID 50143763)
-- Name: admin_benutzer2admin_benutzergruppe_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.admin_benutzer2admin_benutzergruppe_v AS
 SELECT b.anmeldename,
    bg.benutzergruppe,
        CASE
            WHEN (bg.benutzergruppe = 'verundentsorgung_viewer_zvg_gruppe'::text) THEN '%'::text
            WHEN (bg.benutzergruppe = 'verundentsorgung_erfasser_zvg_gruppe'::text) THEN '%'::text
            WHEN (bg.benutzergruppe = 'verundentsorgung_erfasser_wa_zvg_gruppe'::text) THEN 'wa'::text
            WHEN (bg.benutzergruppe = 'verundentsorgung_erfasser_aw_zvg_gruppe'::text) THEN 'aw'::text
            WHEN (bg.benutzergruppe = 'verundentsorgung_erfasser_ka_zvg_gruppe'::text) THEN 'ka'::text
            ELSE NULL::text
        END AS tabellenpraefix,
        CASE
            WHEN ("position"(bg.benutzergruppe, 'viewer'::text) > 0) THEN 'select'::text
            WHEN ("position"(bg.benutzergruppe, 'erfasser'::text) > 0) THEN 'select, insert, update, delete'::text
            ELSE NULL::text
        END AS datenbankrecht,
    b.vorname,
    b.nachname,
    b.email,
    b.titel,
    b.id_st_vw_projekt,
    p.kurztext AS projektname,
    b.id AS id_admin_benutzer,
    bg.id AS id_admin_benutzergruppe,
    b2bg.id AS id_admin_benutzer2admin_benutzergruppe,
    p.gueltig_bis AS gueltig_bis_st_vw_projekt,
    b.gueltig_bis AS gueltig_bis_admin_benutzer,
    bg.gueltig_bis AS gueltig_bis_admin_benutzergruppe,
    b2bg.gueltig_bis AS gueltig_bis_admin_benutzer2admin_benutzergruppe
   FROM verundentsorgung.admin_benutzer b,
    verundentsorgung.admin_benutzer2admin_benutzergruppe b2bg,
    verundentsorgung.admin_benutzergruppe bg,
    verundentsorgung.st_vw_projekt p
  WHERE ((b.id_st_vw_projekt = p.id) AND (b.id = b2bg.id_admin_benutzer) AND (b.id_st_vw_projekt = b2bg.id_st_vw_projekt) AND (bg.id = b2bg.id_admin_benutzergruppe) AND (bg.id_st_vw_projekt = b2bg.id_st_vw_projekt))
  ORDER BY b.anmeldename, bg.benutzergruppe;


