--
-- TOC entry 20943 (class 1259 OID 46618640)
-- Name: admin_layerstruktur2admin_symbole; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.admin_layerstruktur2admin_symbole AS
 SELECT a.anzahl,
    a.projekt,
    a.medium,
    a.objekttyp,
    a.objektklasse,
    a.symbol,
    a.medium_filter_alt,
    a.medium_filter,
    a.betriebsstatus_filter,
    a.lagestatus_filter,
    a.eigentuemer_filter,
    a.betreiber_filter,
    a.darstellung,
    (verundentsorgung.rgb_to_hex((a.rgb_farbe)::text))::character varying AS rgb_farbe,
    a.strichstaerke_mm,
    a.line_style,
    (verundentsorgung.rgb_to_hex((a.line_color)::text))::character varying AS line_color,
    a.line_alpha,
    a.line_width,
    a.line_width_unit,
    a.pkt_symbolname,
    a.pkt_symbolnamelang,
    (verundentsorgung.rgb_to_hex((a.pkt_stroke_color)::text))::character varying AS pkt_stroke_color,
    (verundentsorgung.rgb_to_hex((a.pkt_fill_color)::text))::character varying AS pkt_fill_color,
    a.pkt_stroke_with,
    a.pkt_symbol_size,
    a.pkt_symbol_angle,
    a.medium_gruppe,
    a.symbolname,
    a.symbolname_langtext,
    a.symbol_objektklasse,
    a.symbol_objekttyp,
    a.symbolname_alt,
    a.zeile,
    a.ogc_fid
   FROM ( SELECT DISTINCT count(*) AS anzahl,
            l.projekt,
            l.medium,
            l.objekttyp,
            l.objektklasse,
            l.symbol,
            l.medium_filter_alt,
            l.medium_filter,
            l.betriebsstatus_filter,
            l.lagestatus_filter,
            l.eigentuemer_filter,
            l.betreiber_filter,
            l.darstellung,
            l.rgb_farbe,
            l.strichstaerke_mm,
            l.line_style,
            l.line_color,
            l.line_alpha,
            l.line_width,
            l.line_width_unit,
            l.pkt_symbolname,
            l.pkt_symbolnamelang,
            l.pkt_stroke_color,
            l.pkt_fill_color,
            l.pkt_stroke_with,
            l.pkt_symbol_size,
            l.pkt_symbol_angle,
            l.medium_gruppe,
            s.symbolname,
            s.symbolname_langtext,
            s.objektklasse AS symbol_objektklasse,
            s.objekttyp AS symbol_objekttyp,
            s.symbolname_alt,
            l.zeile,
            l.ogc_fid
           FROM verundentsorgung.admin_layerstruktur l,
            verundentsorgung.admin_symbole s
          WHERE (((l.projekt)::text = (s.projekt)::text) AND (("position"((s.objektklasse)::text, (l.objektklasse)::text) > 0) OR ("position"((l.objektklasse)::text, (s.objektklasse)::text) > 0)))
          GROUP BY l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol, l.medium_filter_alt, l.medium_filter, l.betriebsstatus_filter, l.lagestatus_filter, l.eigentuemer_filter, l.betreiber_filter, l.darstellung, l.rgb_farbe, l.strichstaerke_mm, l.line_style, l.line_color, l.line_alpha, l.line_width, l.line_width_unit, l.pkt_symbolname, l.pkt_symbolnamelang, l.pkt_stroke_color, l.pkt_fill_color, l.pkt_stroke_with, l.pkt_symbol_size, l.pkt_symbol_angle, l.medium_gruppe, s.symbolname, s.symbolname_langtext, s.objektklasse, s.objekttyp, s.symbolname_alt, l.zeile, l.ogc_fid
        UNION ALL
         SELECT DISTINCT count(*) AS anzahl,
            l.projekt,
            l.medium,
            l.objekttyp,
            l.objektklasse,
            l.symbol,
            l.medium_filter_alt,
            l.medium_filter,
            l.betriebsstatus_filter,
            l.lagestatus_filter,
            l.eigentuemer_filter,
            l.betreiber_filter,
            l.darstellung,
            l.rgb_farbe,
            l.strichstaerke_mm,
            l.line_style,
            l.line_color,
            l.line_alpha,
            l.line_width,
            l.line_width_unit,
            l.pkt_symbolname,
            l.pkt_symbolnamelang,
            l.pkt_stroke_color,
            l.pkt_fill_color,
            l.pkt_stroke_with,
            l.pkt_symbol_size,
            l.pkt_symbol_angle,
            l.medium_gruppe,
            ''::text AS symbolname,
            ''::text AS symbolname_langtext,
            l.objektklasse AS symbol_objektklasse,
            ''::text AS symbol_objekttyp,
            ''::text AS symbolname_alt,
            l.zeile,
            l.ogc_fid
           FROM verundentsorgung.admin_layerstruktur l
          GROUP BY l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol, l.medium_filter_alt, l.medium_filter, l.betriebsstatus_filter, l.lagestatus_filter, l.eigentuemer_filter, l.betreiber_filter, l.darstellung, l.rgb_farbe, l.strichstaerke_mm, l.line_style, l.line_color, l.line_alpha, l.line_width, l.line_width_unit, l.pkt_symbolname, l.pkt_symbolnamelang, l.pkt_stroke_color, l.pkt_fill_color, l.pkt_stroke_with, l.pkt_symbol_size, l.pkt_symbol_angle, l.medium_gruppe, l.zeile, l.ogc_fid) a;


