--
-- TOC entry 20944 (class 1259 OID 46618645)
-- Name: admin_table_comments; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.admin_table_comments AS
 SELECT d.table_schema,
    d.table_name,
    d.table_view,
    d.description,
    wsd.aliasname AS websuite_aliasname,
    wsd.teaser AS websuite_teaser,
    wsd.sichtbarkeit AS websuite_sichtbarkeit,
    wsd.editierbarkeit AS websuite_editierbarkeit,
    wsd.load_all AS websuite_load_all
   FROM (( SELECT t.table_schema,
            t.table_name,
            replace((t.table_type)::text, 'BASE TABLE'::text, 'TABLE'::text) AS table_view,
            obj_description(pgc.oid, 'pg_class'::name) AS description
           FROM ((information_schema.tables t
             JOIN pg_class pgc ON (((t.table_name)::name = pgc.relname)))
             JOIN pg_namespace pgn ON (((pgn.oid = pgc.relnamespace) AND (pgn.nspname = (t.table_schema)::name))))
          WHERE (((t.table_schema)::name = 'verundentsorgung'::name) AND ((t.table_type)::text = ANY (ARRAY[('BASE TABLE'::character varying)::text, ('VIEW'::character varying)::text])) AND (pgc.relkind = ANY (ARRAY['r'::"char", 'v'::"char"])))) d
     LEFT JOIN ( SELECT admin_table_dictionary.id,
            admin_table_dictionary.angelegt_am,
            admin_table_dictionary.bemerkung,
            admin_table_dictionary.aliasname,
            admin_table_dictionary.teaser,
            admin_table_dictionary.sichtbarkeit,
            admin_table_dictionary.table_catalog,
            admin_table_dictionary.table_schema,
            admin_table_dictionary.table_name,
            admin_table_dictionary.table_type,
            admin_table_dictionary.gueltig_von,
            admin_table_dictionary.gueltig_bis,
            admin_table_dictionary.editierbarkeit,
            admin_table_dictionary.real_table_name,
            admin_table_dictionary.load_all
           FROM admin.admin_table_dictionary
          WHERE ((admin_table_dictionary.table_schema)::text ~~ 'verundentsorgung_viewer_zvg'::text)) wsd ON (((d.table_name)::text = (wsd.table_name)::text)))
  ORDER BY d.table_schema, d.table_name;


