--
-- TOC entry 22521 (class 1259 OID 61022728)
-- Name: al_fla_koordinatenraster2dokument_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.al_fla_koordinatenraster2dokument_v AS
 SELECT d2o.id,
    concat(r.zahl, r.buchstabe, ', ', d.titel) AS id_suche,
    concat(r.zahl, r.buchstabe) AS name_number,
    d.id_st_vw_projekt,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    "left"((d.gueltig_von)::text, 16) AS gueltig_von,
    "left"((d.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((d.angelegt_am)::text, 10) AS angelegt_am,
    d.angelegt_von,
    "left"((d.geaendert_am)::text, 10) AS geaendert_am,
    d.geaendert_von,
    d.bemerkung,
    d.kommentar,
    d.titel,
    d.datei,
    s.id_st_strasse,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    ''::text AS gemeinde_schluessel,
    r.geometry
   FROM verundentsorgung.al_fla_koordinatenraster r,
    verundentsorgung.st_dokument d,
    verundentsorgung.st_dokument2objekt d2o,
    verundentsorgung.st_vw_projekt p,
    verundentsorgung.strassenschluessel_v s
  WHERE ((r.id_st_vw_projekt = d.id_st_vw_projekt) AND (r.id_st_vw_projekt = d2o.id_st_vw_projekt) AND (r.id_st_vw_projekt = p.id) AND (r.id = d2o.id_objekt) AND (d.id = d2o.id_st_dokument) AND (r.id_st_strasse = s.id) AND (public.st_astext(r.geometry) ~~ 'POLYGON%'::text));


