-- TOC entry 21706 (class 1259 OID 56065231)
-- Name: aw_lin_haltung_richtungspfeil_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_lin_haltung_richtungspfeil_v AS
 SELECT aw_lin_haltung_v.id,
    aw_lin_haltung_v.fid_hist,
    aw_lin_haltung_v.name_number,
    aw_lin_haltung_v.gueltig_von,
    aw_lin_haltung_v.gueltig_bis,
    aw_lin_haltung_v.angelegt_am,
    aw_lin_haltung_v.angelegt_von,
    aw_lin_haltung_v.geaendert_am,
    aw_lin_haltung_v.geaendert_von,
    aw_lin_haltung_v.leistungsobjekt,
    aw_lin_haltung_v.bemerkung,
    aw_lin_haltung_v.id_st_strasse,
    aw_lin_haltung_v.hausnummer,
    aw_lin_haltung_v.hausnummerzusatz,
    aw_lin_haltung_v.lagezusatz,
    aw_lin_haltung_v.herkunftsplan,
    aw_lin_haltung_v.id_st_vw_projekt,
    aw_lin_haltung_v.id_st_vw_betriebsstatus,
    aw_lin_haltung_v.id_st_vw_eigentuemer,
    aw_lin_haltung_v.id_st_vw_betreiber,
    aw_lin_haltung_v.id_st_vw_material,
    aw_lin_haltung_v.id_st_vw_medium,
    aw_lin_haltung_v.id_st_vw_lagestatus,
    aw_lin_haltung_v.amt,
    aw_lin_haltung_v.gemeinde,
    aw_lin_haltung_v.ort,
    aw_lin_haltung_v.strasse,
    aw_lin_haltung_v.projekt_kurztext,
    aw_lin_haltung_v.projekt_langtext,
    aw_lin_haltung_v.betriebsstatus_kurztext,
    aw_lin_haltung_v.betriebsstatus_langtext,
    aw_lin_haltung_v.eigentuemer_kurztext,
    aw_lin_haltung_v.eigentuemer_langtext,
    aw_lin_haltung_v.betreiber_kurztext,
    aw_lin_haltung_v.betreiber_langtext,
    aw_lin_haltung_v.material_kurztext,
    aw_lin_haltung_v.material_langtext,
    aw_lin_haltung_v.medium_kurztext,
    aw_lin_haltung_v.medium_langtext,
    aw_lin_haltung_v.lagestatus_kurztext,
    aw_lin_haltung_v.lagestatus_langtext,
    aw_lin_haltung_v.gelaendehoehe_knoten_oben,
    aw_lin_haltung_v.gelaendehoehe_knoten_unten,
    aw_lin_haltung_v.baujahr,
    aw_lin_haltung_v.id_knoten_oben,
    aw_lin_haltung_v.id_knoten_unten,
    aw_lin_haltung_v.nennweite,
    aw_lin_haltung_v.aussendurchmesser,
    aw_lin_haltung_v.sohle_einlaufschacht,
    aw_lin_haltung_v.fallhoehe_einlaufschacht,
    aw_lin_haltung_v.einlaufnummer,
    aw_lin_haltung_v.ablaufhoehe,
    aw_lin_haltung_v.auslaufnummer,
    aw_lin_haltung_v.einlaufhoehe,
    aw_lin_haltung_v.laenge,
    aw_lin_haltung_v.sohle_ablaufschacht,
    aw_lin_haltung_v.haltungsgefaelle,
    aw_lin_haltung_v.wandstaerke,
    aw_lin_haltung_v.plannummer,
    aw_lin_haltung_v.knoten_oben,
    aw_lin_haltung_v.knoten_unten,
    aw_lin_haltung_v.test,
    aw_lin_haltung_v.verlegetyp_kurztext,
    aw_lin_haltung_v.verlegetyp_langtext,
    aw_lin_haltung_v.layout,
    round((degrees(public.st_azimuth(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry))))::numeric, 2) AS richtungswinkel,
    public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.5)::double precision) AS pkt_haltungsmitte,
    public.st_makeline(public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.5)::double precision), public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.6)::double precision)) AS lin_haltungsmitte,
    public.st_multi(public.st_makeline(public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.5)::double precision), public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.6)::double precision))) AS mlin_haltungsmitte,
    public.st_buffer(public.st_lineinterpolatepoint(public.st_makeline(public.st_startpoint(aw_lin_haltung_v.geometry), public.st_endpoint(aw_lin_haltung_v.geometry)), (0.5)::double precision), (0.3)::double precision) AS fla_haltungsmitte,
    aw_lin_haltung_v.geometry,
    concat(aw_lin_haltung_v.name_number, ' ', 'AW-Richtungspfeil') AS id_suche
   FROM verundentsorgung.aw_lin_haltung_v
  WHERE ((aw_lin_haltung_v.medium_langtext = ANY (ARRAY['Regenwasserkanal'::text, 'Schmutzwasserkanal'::text, 'Mischwasserkanal'::text])) AND (public.st_length(aw_lin_haltung_v.geometry) > (5)::double precision));


