 SELECT l.id,
    l.drehwinkel,
    l.gueltig_von,
    l.gueltig_bis,
    l.angelegt_am,
    l.angelegt_von,
    l.geaendert_am,
    l.geaendert_von,
    l.bemerkung,
    l.id_st_vw_objektbezeichnung,
    l.ident_hist,
    l.ident_object_hist,
    l.titel,
    l.kommentar,
    l.labeltext,
    l.id_st_vw_labeltyp,
    l.id_st_vw_projekt,
    l.id_st_vw_label_definition,
    l.id_objekt,
    l.table_schema,
