--
-- TOC entry 20949 (class 1259 OID 46618701)
-- Name: aw_pkt_benzinabscheider_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_pkt_benzinabscheider_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
    b.bemerkung,
    b.id_st_strasse,
    b.hausnummer,
    b.hausnummerzusatz,
    b.lagezusatz,
    b.herkunftsplan,
    b.id_st_vw_projekt,
    b.id_st_vw_betriebsstatus,
    b.id_st_vw_eigentuemer,
    b.id_st_vw_betreiber,
    b.id_st_vw_material,
    b.id_st_vw_medium,
    b.id_st_vw_lagestatus,
    b.geometry,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    bs.kurztext AS betriebsstatus_kurztext,
    bs.langtext AS betriebsstatus_langtext,
    eig.kurztext AS eigentuemer_kurztext,
    eig.langtext AS eigentuemer_langtext,
    betr.kurztext AS betreiber_kurztext,
    betr.langtext AS betreiber_langtext,
    mat.kurztext AS material_kurztext,
    mat.langtext AS material_langtext,
    med.kurztext AS medium_kurztext,
    med.langtext AS medium_langtext,
    ls.kurztext AS lagestatus_kurztext,
    ls.langtext AS lagestatus_langtext,
    (b.baujahr)::text AS baujahr,
    b.schacht_typ AS schacht_typ_kurztext,
    b.layout,
    concat(b.name_number, ' ', 'AW-Benzinabscheider') AS id_suche
   FROM ((((((((verundentsorgung.aw_pkt_benzinabscheider b
     LEFT JOIN verundentsorgung.strassenschluessel_v s ON ((b.id_st_strasse = s.id)))
     LEFT JOIN verundentsorgung.st_vw_projekt p ON ((b.id_st_vw_projekt = p.id)))
     LEFT JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((b.id_st_vw_betriebsstatus = bs.id)))
     LEFT JOIN verundentsorgung.st_vw_eigentuemer eig ON ((b.id_st_vw_eigentuemer = eig.id)))
     LEFT JOIN verundentsorgung.st_vw_betreiber betr ON ((b.id_st_vw_betreiber = betr.id)))
     LEFT JOIN verundentsorgung.st_vw_material mat ON ((b.id_st_vw_material = mat.id)))
     LEFT JOIN verundentsorgung.st_vw_medium med ON ((b.id_st_vw_medium = med.id)))
     LEFT JOIN verundentsorgung.st_vw_lagestatus ls ON ((b.id_st_vw_lagestatus = ls.id)))
  WHERE (b.gueltig_bis > now());


