-- Name: aw_pkt_schieber_v_label; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_pkt_schieber_v_label AS
 SELECT l.id,
    l.drehwinkel,
    l.gueltig_von,
    l.gueltig_bis,
    l.angelegt_am,
    l.angelegt_von,
    l.geaendert_am,
    l.geaendert_von,
    l.bemerkung,
    l.id_st_vw_objektbezeichnung,
    l.ident_hist,
    l.ident_object_hist,
    l.titel,
    l.kommentar,
    l.labeltext,
    l.id_st_vw_labeltyp,
    l.id_st_vw_projekt,
    l.id_st_vw_label_definition,
    l.id_objekt,
    l.table_schema,
    l.table_name,
    l.projekt_kurztext,
    l.projekt_langtext,
    l.labeltyp_kurztext,
    l.labeltyp_langtext,
    l.label_definition_kurztext,
    l.label_definition_langtext,
    l.geometry,
    l.id_suche,
    l.layout
   FROM verundentsorgung.aw_pkt_label_v l,
    verundentsorgung.aw_pkt_schieber s
  WHERE (l.id_objekt = s.id);


