    z.strasse
   FROM (( SELECT d.id,
            d.dateiname,
            d.id_st_vw_projekt,
            d.name_number,
            d.protokolltyp,
            d.befahrungsdatum,
            d.befahrungsjahr,
            d.befahrungsmonat,
            d.befahrungstag,
            d.schadensklasse,
