-- TOC entry 21707 (class 1259 OID 56065236)
-- Name: isybau_export; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.isybau_export AS
 SELECT h.name_number,
        CASE
            WHEN (h.medium_langtext ~~ 'Schmutz%'::text) THEN 'KS'::text
            WHEN (h.medium_langtext ~~ 'Regen%'::text) THEN 'KR'::text
            ELSE NULL::text
        END AS kanalart,
        CASE
            WHEN (h.material_langtext = 'Kunststoff/Glasfaserverstärkter Kunststoff'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Stahlbeton'::text) THEN '0.5'::text
            WHEN (h.material_langtext = 'Polyethylen 80'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'doppelwandiges Kunststoffrohr'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'unterschiedliche Werkstoffe'::text) THEN '0.3'::text
            WHEN (h.material_langtext = 'FLEX'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Beton/Glasfaserverstärkter Kunststoff'::text) THEN '0.5'::text
            WHEN (h.material_langtext = 'Glasfaserverstärkter Kunststoff'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Grauguss'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Asbestzement'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Stahl'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Steinzeug/Glasfaserverstärkter Kunststoff'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Duktiles Gusseisen'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Edelstahl'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Polyethylen hoher Dichte'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Ton'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Polyethylen 100'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Wandverstärkter Schwerlastbeton'::text) THEN '0.5'::text
            WHEN (h.material_langtext = 'Polyethylen'::text) THEN '0.1'::text
            WHEN ((h.material_langtext IS NULL) OR (h.material_langtext = ''::text) OR (h.material_langtext = ' '::text)) THEN '0.3'::text
            WHEN (h.material_langtext = 'Polypropylen'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'unbekannt'::text) THEN '0.3'::text
            WHEN (h.material_langtext = 'Polyvinylchlorid hart'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Steinzeug'::text) THEN '0.1'::text
            WHEN (h.material_langtext = 'Beton'::text) THEN '0.5'::text
            ELSE NULL::text
        END AS rauhigkeit,
    'Normalschacht'::text AS funktion,
    h.bemerkung,
    h.amt,
    h.gemeinde,
    h.ort,
    h.strasse,
    h.hausnummer,
    h.baujahr,
    h.material_langtext AS material,
    h.eigentuemer_langtext AS eigentuemer,
    h.betreiber_langtext AS betreiber,
        CASE
            WHEN (h.material_langtext = 'Kunststoff/Glasfaserverstärkter Kunststoff'::text) THEN 'GfK'::text
            WHEN (h.material_langtext = 'Stahlbeton'::text) THEN 'B'::text
            WHEN (h.material_langtext = 'Polyethylen 80'::text) THEN 'PE'::text
            WHEN (h.material_langtext = 'doppelwandiges Kunststoffrohr'::text) THEN 'BKU'::text
            WHEN (h.material_langtext = 'unterschiedliche Werkstoffe'::text) THEN 'MIX'::text
            WHEN (h.material_langtext = 'FLEX'::text) THEN 'KST'::text
            WHEN (h.material_langtext = 'Beton/Glasfaserverstärkter Kunststoff'::text) THEN 'BKU'::text
            WHEN (h.material_langtext = 'Glasfaserverstärkter Kunststoff'::text) THEN 'GfK'::text
            WHEN (h.material_langtext = 'Grauguss'::text) THEN 'GG'::text
            WHEN (h.material_langtext = 'Asbestzement'::text) THEN 'Az'::text
            WHEN (h.material_langtext = 'Stahl'::text) THEN 'St'::text
            WHEN (h.material_langtext = 'Steinzeug/Glasfaserverstärkter Kunststoff'::text) THEN 'GfK'::text
            WHEN (h.material_langtext = 'Duktiles Gusseisen'::text) THEN 'GGG'::text
            WHEN (h.material_langtext = 'Edelstahl'::text) THEN 'CNS'::text
            WHEN (h.material_langtext = 'Polyethylen hoher Dichte'::text) THEN 'PEHD'::text
            WHEN (h.material_langtext = 'Ton'::text) THEN 'Stz'::text
            WHEN (h.material_langtext = 'Polyethylen 100'::text) THEN 'PE'::text
            WHEN (h.material_langtext = 'Wandverstärkter Schwerlastbeton'::text) THEN 'B'::text
            WHEN (h.material_langtext = 'Polyethylen'::text) THEN 'PE'::text
            WHEN ((h.material_langtext IS NULL) OR (h.material_langtext = ''::text) OR (h.material_langtext = ' '::text)) THEN 'MIX'::text
            WHEN (h.material_langtext = 'Polypropylen'::text) THEN 'PP'::text
            WHEN (h.material_langtext = 'unbekannt'::text) THEN 'MIX'::text
