    public.st_geomfromtext(concat('POINT(', (round((public.st_x(public.st_endpoint(h.geometry)))::numeric, 2))::text, ' ', (round((public.st_y(public.st_endpoint(h.geometry)))::numeric, 2))::text, ')'), 25833) AS knoten_unten_geometry,
    h.einlaufhoehe,
