    fu.name_number AS name_number_unten,
    fo.strasse AS ver_strasse_oben,
    fu.strasse AS ver_strasse_unten,
    fo.sohlhoehe AS ver_sohlhoehe_oben,
    fu.sohlhoehe AS ver_sohlhoehe_unten,
