    diu.baujahr AS ein_baujahr_unten,
    dio.baujahr AS ein_baujahr_oben,
    h.nennweite AS profilhoehe,
    h.nennweite AS profilbreite
   FROM ((((((((((verundentsorgung.aw_lin_haltung_v h
     LEFT JOIN verundentsorgung.aw_pkt_schacht_v so ON ((h.knoten_oben = so.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_schacht_v su ON ((h.knoten_unten = su.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_verbindungen_v fo ON ((h.knoten_oben = fo.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_verbindungen_v fu ON ((h.knoten_unten = fu.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_auslauf_v oo ON ((h.knoten_oben = oo.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_auslauf_v ou ON ((h.knoten_unten = ou.name_number)))
