CREATE TABLE verundentsorgung.ka_pkt_label (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    drehwinkel numeric(10,2) DEFAULT 0 NOT NULL,
    gueltig_von timestamp with time zone DEFAULT now() NOT NULL,
    gueltig_bis timestamp with time zone DEFAULT '2100-01-01 00:00:00+01'::timestamp with time zone NOT NULL,
    angelegt_am timestamp with time zone DEFAULT now() NOT NULL,
    angelegt_von text DEFAULT 'unbekannt'::text NOT NULL,
    geaendert_am timestamp with time zone DEFAULT now() NOT NULL,
    geaendert_von text DEFAULT 'unbekannt'::text NOT NULL,
    bemerkung text,
    id_st_vw_objektbezeichnung uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    ident_hist text DEFAULT 'unbekannt'::text NOT NULL,
    ident_object_hist text DEFAULT 'unbekannt'::text NOT NULL,
    titel text DEFAULT 'unbekannt'::text NOT NULL,
    kommentar text DEFAULT 'unbekannt'::text NOT NULL,
    labeltext text DEFAULT 'unbekannt'::text NOT NULL,
    id_st_vw_labeltyp uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_projekt uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_label_definition uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid,
    id_objekt uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid,
    layout jsonb,
    geometry public.geometry(Point,25833),
    name_number character varying DEFAULT (gen_random_uuid())::text NOT NULL,
    id_st_strasse uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL
);


