--
-- TOC entry 20977 (class 1259 OID 46619233)
-- Name: ka_pkt_label_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.ka_pkt_label_v AS
 SELECT DISTINCT l.id,
    l.drehwinkel,
    l.gueltig_von,
    l.gueltig_bis,
    l.angelegt_am,
    l.angelegt_von,
    l.geaendert_am,
    l.geaendert_von,
    l.bemerkung,
    l.id_st_vw_objektbezeichnung,
    l.ident_hist,
    l.ident_object_hist,
    l.titel,
    l.kommentar,
    l.labeltext,
    l.id_st_vw_labeltyp,
    l.id_st_vw_projekt,
    l.id_st_vw_label_definition,
    l.id_objekt,
    ob.table_schema,
    ob.table_name,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    lt.kurztext AS labeltyp_kurztext,
    lt.langtext AS labeltyp_langtext,
    ld.kurztext AS label_definition_kurztext,
    ld.langtext AS label_definition_langtext,
    l.geometry,
    l.layout,
    concat((l.id)::text, ' ', ob.table_name, ' ', 'KA-Label') AS id_suche
   FROM verundentsorgung.ka_pkt_label l,
    verundentsorgung.st_vw_projekt p,
    verundentsorgung.st_vw_labeltyp lt,
    verundentsorgung.st_vw_label_definition ld,
    verundentsorgung.st_vw_objektbezeichnung ob
  WHERE ((l.id_st_vw_projekt = p.id) AND (lt.id = l.id_st_vw_labeltyp) AND (lt.id_st_vw_projekt = p.id) AND (ld.id_st_vw_projekt = p.id) AND (ob.id_st_vw_projekt = p.id) AND (l.id_st_vw_label_definition = ld.id) AND (l.id_st_vw_objektbezeichnung = ob.id) AND (p.gueltig_bis > now()) AND (l.gueltig_bis > now()) AND (lt.gueltig_bis > now()) AND (ld.gueltig_bis > now()) AND (ob.gueltig_bis > now()));


