-- TOC entry 20978 (class 1259 OID 46619238)
-- Name: pdf_name_number_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.pdf_name_number_v AS
 SELECT b.id,
    b.datum,
    b.name_number,
    b."left",
    h.wkb_geometry
   FROM (( SELECT a.id,
            a.datum,
            a.name_number,
            split_part("left"(a.name_number, '-4'::integer), '_'::text, 1) AS "left"
           FROM kanio_views.pdf_name_number a) b
     LEFT JOIN bereitschaftsauskunft.v_ww_section_s_concat h ON (((h.name_number)::text = b."left")))
  WHERE (h.wkb_geometry IS NOT NULL);


