CREATE VIEW verundentsorgung.schacht_test_kann_weg_v AS
 SELECT aw_pkt_schacht.id,
    aw_pkt_schacht.fid_hist,
    aw_pkt_schacht.name_number,
    aw_pkt_schacht.gueltig_von,
    aw_pkt_schacht.gueltig_bis,
    aw_pkt_schacht.angelegt_am,
    aw_pkt_schacht.angelegt_von,
    aw_pkt_schacht.geaendert_am,
    aw_pkt_schacht.geaendert_von,
    aw_pkt_schacht.leistungsobjekt,
    aw_pkt_schacht.bemerkung,
    aw_pkt_schacht.id_st_strasse,
    aw_pkt_schacht.hausnummer,
    aw_pkt_schacht.hausnummerzusatz,
    aw_pkt_schacht.lagezusatz,
    aw_pkt_schacht.herkunftsplan,
    aw_pkt_schacht.id_st_vw_projekt,
    aw_pkt_schacht.id_st_vw_betriebsstatus,
    aw_pkt_schacht.id_st_vw_eigentuemer,
    aw_pkt_schacht.id_st_vw_betreiber,
    aw_pkt_schacht.id_st_vw_material,
    aw_pkt_schacht.id_st_vw_medium,
    aw_pkt_schacht.id_st_vw_lagestatus,
    aw_pkt_schacht.geometry,
    aw_pkt_schacht.baujahr,
    aw_pkt_schacht.migrationsdatum,
    aw_pkt_schacht.id_suche,
    aw_pkt_schacht.sohlhoehe,
    aw_pkt_schacht.tiefe,
    aw_pkt_schacht.deckelhoehe,
    aw_pkt_schacht.orientation,
    aw_pkt_schacht.zvg_leo,
    aw_pkt_schacht.dn,
    aw_pkt_schacht.anz_dokumente,
    aw_pkt_schacht.id_st_vw_schacht_typ,
    aw_pkt_schacht.id_st_vw_schachtdeckeltyp,
    aw_pkt_schacht.id_st_vw_schachtform,
    aw_pkt_schacht.id_st_vw_einstiegshilfe,
    aw_pkt_schacht.id_st_vw_beschichtung,
    aw_pkt_schacht.layout,
    aw_pkt_schacht.okg,
    (aw_pkt_schacht.layout -> 'hex_pkt_stroke_color'::text) AS farbe
   FROM verundentsorgung.aw_pkt_schacht;


