--
-- TOC entry 22523 (class 1259 OID 61022779)
-- Name: st_fla_koordinatenraster_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.st_fla_koordinatenraster_v AS
 SELECT b.id,
    b.koordinatenraster AS id_suche,
    b.koordinatenraster AS name_number,
    b.id_st_vw_projekt,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    s.id_st_strasse,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    i.medium,
    i.planerstellungsdatum,
    i.planvorhabenbeschriftung,
    i.dateiname,
    concat(
        CASE
            WHEN (p.kurztext = 'ZKWAL'::text) THEN '/dokumente/extern_dateianbindung/zkwal/pdf/'::text
            ELSE NULL::text
        END, i.dateiname) AS datei_pfad,
    b.geometry
   FROM (((((((((verundentsorgung.st_fla_koordinatenraster b
     LEFT JOIN verundentsorgung.fremd_zkwal_dateinamen_import i ON ((b.koordinatenraster = i.koordinatengitter)))
     LEFT JOIN verundentsorgung.strassenschluessel_v s ON ((b.id_st_strasse = s.id)))
     LEFT JOIN verundentsorgung.st_vw_projekt p ON ((b.id_st_vw_projekt = p.id)))
     LEFT JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((b.id_st_vw_betriebsstatus = bs.id)))
     LEFT JOIN verundentsorgung.st_vw_eigentuemer eig ON ((b.id_st_vw_eigentuemer = eig.id)))
     LEFT JOIN verundentsorgung.st_vw_betreiber betr ON ((b.id_st_vw_betreiber = betr.id)))
     LEFT JOIN verundentsorgung.st_vw_material mat ON ((b.id_st_vw_material = mat.id)))
     LEFT JOIN verundentsorgung.st_vw_medium med ON ((b.id_st_vw_medium = med.id)))
     LEFT JOIN verundentsorgung.st_vw_lagestatus ls ON ((b.id_st_vw_lagestatus = ls.id)))
  WHERE (public.st_astext(b.geometry) ~~ 'POLYGON%'::text);


