 SELECT DISTINCT a.kurztext,
    a.langtext,
    a.id,
    a.tabellenname,
    b.symbolname
   FROM (( SELECT st_vw_abscheidertyp.id,
            st_vw_abscheidertyp.kurztext,
            st_vw_abscheidertyp.langtext,
            'st_vw_abscheidertyp'::text AS tabellenname
           FROM verundentsorgung.st_vw_abscheidertyp
        UNION ALL
         SELECT st_vw_abwassereinleittyp.id,
            st_vw_abwassereinleittyp.kurztext,
            st_vw_abwassereinleittyp.langtext,
            'st_vw_abwassereinleittyp'::text AS tabellenname
           FROM verundentsorgung.st_vw_abwassereinleittyp
        UNION ALL
         SELECT st_vw_auslauftyp.id,
            st_vw_auslauftyp.kurztext,
