CREATE VIEW verundentsorgung.st_vw_label_definition_v AS
 SELECT a.id,
    a.ident_hist,
    a.kurztext,
    a.langtext,
    a.attributregel,
    b.langtext AS table_name,
    a.bemerkung,
    a.sortierreihenfolge,
    a.gueltig_von,
    a.gueltig_bis,
    a.angelegt_am,
    a.angelegt_von,
    a.geaendert_am,
