    a.id_st_vw_projekt,
    a.table_schema,
    a.geometrieregel,
    a.attributregel_aktivstatus,
    a.geometrieregel_aktivstatus,
    a.id_st_vw_objektbezeichnung,
    a.id_st_vw_labeltyp
   FROM (verundentsorgung.st_vw_label_definition a
     LEFT JOIN verundentsorgung.st_vw_objektbezeichnung b ON ((a.id_st_vw_objektbezeichnung = b.id)))
  WHERE (1 = 1);


