    b.ident_hist,
    b.kurztext,
    b.langtext,
    concat(b.kurztext, ' (', b.langtext, ')') AS anzeige,
    b.bemerkung,
    b.sortierreihenfolge,
    b.gueltig_von,
    b.gueltig_bis,
    b.angelegt_am,
    b.angelegt_von,
    b.geaendert_am,
    b.geaendert_von,
    b.id_st_vw_projekt
   FROM verundentsorgung.st_vw_zaehlertyp b;


